  aether: { name: 'Aether', color: '#ffd98b', dark: '#5a4626', icon: '✦', glyph: '✦' }
}

const STRONG = {
  bloom: ['tide', 'stone'],
  ember: ['bloom', 'frost'],
  tide: ['ember', 'stone'],
  frost: ['bloom', 'storm'],
  storm: ['tide', 'frost'],
  stone: ['ember', 'storm'],
  umbra: ['storm', 'aether'],
  aether: ['umbra']
}

const RESIST = {
  bloom: ['ember', 'frost'],
  ember: ['tide', 'stone'],
  tide: ['bloom', 'storm'],
  frost: ['ember', 'stone'],
  storm: ['stone', 'umbra'],
  stone: ['bloom', 'tide'],
  umbra: ['bloom', 'aether'],
  aether: ['aether', 'storm']
}

export function typeMultiplier(attackType, defendType) {
  if (STRONG[attackType]?.includes(defendType)) return 1.55
  if (RESIST[attackType]?.includes(defendType)) return 0.68
  return 1
}

