  --night: #0b1020;
  --panel: rgba(10, 15, 28, 0.78);
  --panel-2: rgba(15, 22, 38, 0.92);
  --line: rgba(255, 238, 194, 0.16);
  --line-strong: rgba(255, 224, 151, 0.4);
  --gold: #f2c96d;
  --gold-2: #ffe6a3;
  --cream: #fff8e7;
  --muted: #aab2c5;
  --teal: #73ead2;
  --danger: #ff766b;
  --ok: #78e4a2;
  --shadow: 0 24px 90px rgba(0, 0, 0, 0.55);
