* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: var(--ink); color: var(--cream); }
body { font-family: var(--sans); -webkit-font-smoothing: antialiased; user-select: none; }
button, input { font: inherit; color: inherit; }
button { cursor: pointer; }
#app { position: fixed; inset: 0; overflow: hidden; }
#scene-host { position: absolute; inset: 0; }
#scene-host canvas { display: block; width: 100%; height: 100%; touch-action: none; }
.hidden { display: none !important; }

#vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at 50% 46%, transparent 48%, rgba(3, 6, 12, 0.38) 100%); z-index: 2; }
#grain { position: absolute; inset: -20%; pointer-events: none; opacity: 0.055; z-index: 3; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.7'/%3E%3C/svg%3E"); animation: grainShift 0.7s steps(2) infinite; }
@keyframes grainShift { 0% { transform: translate(0,0); } 25% { transform: translate(-2%, 1%); } 50% { transform: translate(1%, -2%); } 75% { transform: translate(2%, 2%); } 100% { transform: translate(-1%, -1%); } }
#flash { position: absolute; inset: 0; pointer-events: none; background: #fff; opacity: 0; z-index: 30; transition: opacity 0.12s; mix-blend-mode: screen; }
#flash.on { opacity: 0.42; }
#flash.red { background: #ff8b70; }

.screen { position: absolute; inset: 0; z-index: 10; }
.screen.active { display: block; }

/* ---------- loading ---------- */
#loading-screen { display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 40%, #1c2740 0%, #090c16 62%); z-index: 100; transition: opacity 0.7s ease, visibility 0.7s; }
#loading-screen.out { opacity: 0; visibility: hidden; }
.load-emblem { font-size: 2rem; color: var(--gold); text-shadow: 0 0 24px rgba(242, 201, 109, 0.75); animation: pulse 2s ease-in-out infinite; }
.load-title { margin-top: 14px; font-family: var(--serif); font-size: clamp(2.5rem, 5vw, 4.4rem); letter-spacing: 0.18em; font-weight: 600; }
.load-track { width: 220px; height: 2px; margin-top: 32px; background: rgba(255,255,255,0.12); overflow: hidden; }
#load-fill { width: 6%; height: 100%; background: linear-gradient(90deg, var(--teal), var(--gold)); transition: width 0.4s; box-shadow: 0 0 18px var(--gold); }
.load-copy { margin-top: 16px; font-size: 0.66rem; letter-spacing: 0.26em; color: var(--muted); text-transform: uppercase; }
@keyframes pulse { 0%, 100% { opacity: 0.55; transform: scale(0.94); } 50% { opacity: 1; transform: scale(1.06); } }

