.btn-ghost:hover { border-color: var(--line-strong); background: rgba(22, 32, 52, 0.7); }
.btn-ghost i { color: var(--gold); font-style: normal; }
.text-btn { border: 0; background: transparent; color: var(--gold); font-size: 0.7rem; letter-spacing: 0.12em; text-transform: uppercase; padding: 8px 2px; }
.text-btn:hover { color: var(--gold-2); }
.icon-btn { width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--line); background: rgba(9, 14, 25, 0.65); display: grid; place-items: center; transition: 0.2s; }
.icon-btn:hover { border-color: var(--gold); color: var(--gold); }
.brand-mark { display: flex; align-items: center; gap: 10px; font-family: var(--serif); font-size: 0.88rem; letter-spacing: 0.2em; font-weight: 600; }
.brand-mark.small { font-size: 0.72rem; }
.brand-sigil { color: var(--gold); font-size: 1.2em; text-shadow: 0 0 16px rgba(242,201,109,0.6); }
.panel-eyebrow { display: flex; align-items: center; gap: 10px; font-size: 0.6rem; letter-spacing: 0.28em; text-transform: uppercase; color: var(--gold); font-weight: 600; }
.panel-eyebrow::before { content: ''; width: 26px; height: 1px; background: var(--gold); opacity: 0.7; }
.hidden { display: none !important; }

/* ---------- title ---------- */
#title-screen { overflow: hidden; }
#title-screen::before { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(5,8,16,0.75) 0%, rgba(5,8,16,0.18) 42%, transparent 70%), linear-gradient(0deg, rgba(5,8,16,0.72), transparent 36%); pointer-events: none; }
.title-topbar { position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: center; padding: 28px 4vw; z-index: 2; }
.title-top-meta { font-size: 0.58rem; letter-spacing: 0.3em; color: rgba(255,248,231,0.55); }
.title-main { position: absolute; left: 7vw; top: 22%; width: min(720px, 70vw); z-index: 2; animation: riseIn 1.1s cubic-bezier(.18,.9,.25,1) both; }
.title-kicker { display: flex; align-items: center; gap: 14px; font-size: 0.61rem; letter-spacing: 0.32em; color: var(--gold-2); font-weight: 500; margin-bottom: 12px; }
.title-kicker span { width: 42px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.title-kicker span:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.game-title { margin: 0; font-family: var(--serif); font-size: clamp(4.6rem, 10vw, 10.5rem); line-height: 0.84; letter-spacing: -0.035em; font-weight: 600; text-shadow: 0 20px 80px rgba(0,0,0,0.55); }
.game-title span { display: block; background: linear-gradient(180deg, #fff4cc 0%, #ecc66c 60%, #9a6c25 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 8px 30px rgba(0,0,0,0.3)); }
.title-sub { margin: 24px 0 0; max-width: 390px; font-size: 0.98rem; line-height: 1.75; color: rgba(255,248,231,0.74); font-weight: 300; }
.title-sub br { opacity: 0.7; }
.title-actions { display: flex; align-items: center; gap: 14px; margin-top: 34px; }
.title-stats { display: flex; gap: 36px; margin-top: 36px; padding-top: 22px; border-top: 1px solid rgba(255,255,255,0.12); width: fit-content; }
.title-stats div { display: flex; flex-direction: column; gap: 4px; }
.title-stats strong { font-family: var(--serif); font-size: 1.55rem; font-weight: 500; color: var(--gold-2); }
.title-stats span { font-size: 0.53rem; letter-spacing: 0.2em; color: rgba(255,248,231,0.48); }
.title-footer { position: absolute; bottom: 26px; left: 4vw; right: 4vw; display: flex; justify-content: space-between; font-size: 0.56rem; letter-spacing: 0.16em; color: rgba(255,248,231,0.42); text-transform: uppercase; z-index: 2; }
@keyframes riseIn { from { opacity: 0; transform: translateY(26px); } to { opacity: 1; transform: none; } }

/* ---------- creator ---------- */
#creator-screen { overflow: hidden; }
#creator-screen::before { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(4,7,14,0.82) 0%, rgba(4,7,14,0.35) 36%, transparent 70%), linear-gradient(0deg, rgba(4,7,14,0.82), transparent 45%); pointer-events: none; }
.creator-top { position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: center; padding: 26px 4vw; z-index: 4; }
.step-dots { display: flex; align-items: center; gap: 18px; }
.step-dot { display: flex; align-items: center; gap: 8px; font-size: 0.63rem; letter-spacing: 0.18em; text-transform: uppercase; color: rgba(255,248,231,0.38); transition: 0.3s; }
.step-dot b { display: grid; place-items: center; width: 24px; height: 24px; border: 1px solid rgba(255,255,255,0.18); border-radius: 50%; font-size: 0.53rem; font-weight: 500; }
.step-dot.active { color: var(--gold-2); }
.step-dot.active b { border-color: var(--gold); color: var(--gold); box-shadow: 0 0 14px rgba(242,201,109,0.25); }
.step-line { width: 38px; height: 1px; background: rgba(255,255,255,0.14); }
.creator-layout { position: absolute; inset: 0; z-index: 3; }
.creator-panel { position: absolute; left: 4vw; top: 50%; transform: translateY(-45%); width: min(424px, 39vw); max-height: 82vh; overflow-y: auto; padding: 28px 30px 24px; border-radius: 2px; }
.creator-panel::-webkit-scrollbar { width: 4px; }
.creator-panel::-webkit-scrollbar-thumb { background: rgba(255,224,151,0.24); }
.creator-panel h2 { margin: 12px 0 26px; font-family: var(--serif); font-size: 2rem; line-height: 1.16; font-weight: 500; }
.creator-panel h2 em, .starter-heading h2 em { font-style: normal; color: var(--gold); }
.field { margin-bottom: 19px; }
.field > label, .field > div > label { display: block; margin-bottom: 9px; font-size: 0.53rem; letter-spacing: 0.24em; color: rgba(255,248,231,0.44); font-weight: 500; }
.field input { width: 100%; height: 40px; border: 1px solid var(--line); background: rgba(5,9,17,0.55); padding: 0 13px; font-size: 0.9rem; letter-spacing: 0.06em; outline: none; border-radius: 2px; transition: 0.2s; }
.field input:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(242,201,109,0.1); }
.segmented { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--line); background: rgba(5,9,17,0.45); }
.segmented button { height: 38px; border: 0; background: transparent; color: var(--muted); font-size: 0.7rem; letter-spacing: 0.12em; text-transform: uppercase; transition: 0.2s; }
.segmented button span { margin-right: 6px; font-size: 0.9rem; }
.segmented button.active { background: rgba(242,201,109,0.12); color: var(--gold-2); box-shadow: inset 0 0 0 1px rgba(242,201,109,0.27); }
.swatches { display: flex; gap: 9px; flex-wrap: wrap; }
.swatches.compact { gap: 7px; }
.swatch { width: 30px; height: 30px; border-radius: 50%; border: 2px solid transparent; outline: 1px solid rgba(255,255,255,0.12); outline-offset: 2px; transition: 0.18s; position: relative; }
.swatches.compact .swatch { width: 24px; height: 24px; }
.swatch:hover { transform: scale(1.12); }
.swatch.active { border-color: var(--gold-2); outline-color: rgba(242,201,109,0.55); box-shadow: 0 0 16px rgba(242,201,109,0.25); }
.hair-row { display: flex; gap: 6px; flex-wrap: wrap; }
.hair-opt { width: 43px; height: 32px; border: 1px solid var(--line); background: rgba(5,9,17,0.45); border-radius: 2px; font-size: 0.53rem; letter-spacing: 0.06em; color: var(--muted); text-transform: uppercase; }
.hair-opt.active { color: var(--gold-2); border-color: rgba(242,201,109,0.55); background: rgba(242,201,109,0.1); }
.two-col { display: grid; grid-template-columns: 1.2fr 1fr; gap: 18px; }
.creator-actions { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: 25px; padding-top: 19px; border-top: 1px solid var(--line); }
.creator-actions .btn { min-height: 46px; padding: 0 18px; font-size: 0.65rem; gap: 12px; }
.creator-hint { position: absolute; right: 4vw; bottom: 6vh; display: flex; gap: 14px; align-items: center; padding: 14px 18px; border-radius: 2px; max-width: 310px; }
.hint-icon { color: var(--gold); font-size: 1.2rem; }
.creator-hint strong { display: block; font-size: 0.72rem; margin-bottom: 3px; }
.creator-hint span { font-size: 0.66rem; line-height: 1.55; color: var(--muted); }
.starter-layout { pointer-events: none; }
.starter-heading { position: absolute; left: 6vw; top: 15%; max-width: 470px; pointer-events: auto; }
.starter-heading h2 { margin: 12px 0 12px; font-family: var(--serif); font-size: clamp(2rem, 3.2vw, 3.2rem); line-height: 1.13; font-weight: 500; }
.starter-heading p { max-width: 390px; color: rgba(255,248,231,0.63); font-size: 0.8rem; line-height: 1.7; font-weight: 300; }
.starter-cards { position: absolute; bottom: 8vh; left: 50%; transform: translateX(-50%); width: min(1080px, 90vw); display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; pointer-events: auto; }
.starter-card { position: relative; padding: 20px 20px 17px; min-height: 188px; text-align: left; border: 1px solid var(--line); background: linear-gradient(160deg, rgba(15,23,40,0.88), rgba(7,11,20,0.82)); box-shadow: var(--shadow); backdrop-filter: blur(16px); transition: 0.25s; overflow: hidden; cursor: pointer; }
.starter-card::after { content: ''; position: absolute; inset: 0; border: 1px solid transparent; transition: 0.25s; pointer-events: none; }
.starter-card:hover, .starter-card.active { transform: translateY(-6px); background: linear-gradient(160deg, rgba(24,36,58,0.95), rgba(9,14,25,0.9)); }
.starter-card.active::after { border-color: var(--sc, var(--gold)); box-shadow: inset 0 0 45px color-mix(in srgb, var(--sc, var(--gold)) 18%, transparent); }
.starter-card .card-num { position: absolute; top: 14px; right: 16px; font-size: 0.55rem; letter-spacing: 0.2em; color: rgba(255,255,255,0.25); }
.starter-card .type-chip { display: inline-flex; align-items: center; gap: 5px; padding: 4px 8px; font-size: 0.52rem; letter-spacing: 0.15em; text-transform: uppercase; border: 1px solid var(--sc); color: var(--sc); background: color-mix(in srgb, var(--sc) 11%, transparent); margin-bottom: 12px; }
.starter-card h3 { margin: 0; font-family: var(--serif); font-size: 1.45rem; font-weight: 500; }
.starter-card .epithet { display: block; margin-top: 4px; font-size: 0.57rem; letter-spacing: 0.17em; text-transform: uppercase; color: var(--sc); }
.starter-card p { margin: 12px 0 0; font-size: 0.69rem; line-height: 1.6; color: rgba(255,248,231,0.58); }
.starter-card .pick-line { margin-top: 15px; display: flex; align-items: center; justify-content: space-between; border-top: 1px solid var(--line); padding-top: 10px; font-size: 0.52rem; letter-spacing: 0.17em; color: rgba(255,255,255,0.42); }
.starter-card.active .pick-line { color: var(--gold-2); }
.starter-actions { position: absolute; right: 5vw; bottom: 2.2vh; display: flex; gap: 12px; pointer-events: auto; }
.starter-actions .btn { min-height: 46px; }
.starter-actions .btn-ghost { font-size: 0.63rem; }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 12; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button, #hud .party-dock, #hud .badge-rack, #hud .minimap-wrap { pointer-events: auto; }
.hud-top { position: absolute; top: 0; left: 0; right: 0; padding: 22px 28px; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
.hud-left { display: flex; flex-direction: column; gap: 10px; }
.region-badge { display: flex; align-items: center; gap: 13px; padding: 11px 15px 11px 12px; background: linear-gradient(100deg, rgba(10,15,27,0.82), rgba(10,15,27,0.3)); border-left: 2px solid var(--gold); backdrop-filter: blur(14px); min-width: 288px; }
.region-index { font-family: var(--serif); font-size: 1.55rem; color: var(--gold); opacity: 0.8; }
.region-badge strong { display: block; font-family: var(--serif); font-size: 1.02rem; letter-spacing: 0.05em; font-weight: 500; }
.region-badge div span { display: block; margin-top: 2px; font-size: 0.56rem; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(255,248,231,0.48); }
.region-type { margin-left: auto; font-size: 0.49rem; letter-spacing: 0.17em; text-transform: uppercase; color: var(--type, var(--teal)); border: 1px solid color-mix(in srgb, var(--type, var(--teal)) 40%, transparent); padding: 4px 7px; background: color-mix(in srgb, var(--type, var(--teal)) 9%, transparent); }
.objective { display: flex; align-items: center; gap: 11px; padding: 9px 14px; min-width: 268px; }
.obj-mark { color: var(--gold); font-size: 1rem; }
.objective b { display: block; font-size: 0.48rem; letter-spacing: 0.22em; color: var(--gold); font-weight: 600; }
.objective span:last-child { display: block; margin-top: 3px; font-size: 0.7rem; color: rgba(255,248,231,0.72); }
.hud-center { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.badge-rack { display: flex; gap: 7px; padding: 8px 11px; border-radius: 2px; }
.badge-slot { width: 28px; height: 34px; display: grid; place-items: center; clip-path: polygon(50% 0, 93% 24%, 85% 82%, 50% 100%, 15% 82%, 7% 24%); background: rgba(255,255,255,0.055); border: 1px solid rgba(255,255,255,0.12); font-size: 0.75rem; color: rgba(255,255,255,0.19); position: relative; }
.badge-slot.earned { background: linear-gradient(160deg, color-mix(in srgb, var(--bc) 45%, #111), color-mix(in srgb, var(--bc) 15%, #0a0f1b)); color: var(--bc); text-shadow: 0 0 12px var(--bc); box-shadow: 0 0 16px color-mix(in srgb, var(--bc) 25%, transparent); }
.badge-slot.earned::after { content: ''; position: absolute; inset: 4px; border: 1px solid color-mix(in srgb, var(--bc) 40%, transparent); clip-path: inherit; }
.keeper-chip { display: flex; align-items: center; gap: 9px; padding: 7px 13px 7px 7px; background: rgba(10,15,27,0.6); border: 1px solid var(--line); backdrop-filter: blur(12px); }
.keeper-chip > span { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(145deg, #f4d889, #b7882e); color: #19130a; font-family: var(--serif); font-size: 0.95rem; font-weight: 700; }
.keeper-chip b { display: block; font-size: 0.68rem; letter-spacing: 0.08em; }
.keeper-chip i { display: block; margin-top: 2px; font-size: 0.48rem; color: var(--gold); letter-spacing: 0.13em; text-transform: uppercase; font-style: normal; }
.hud-right { display: flex; align-items: flex-start; gap: 13px; }
.minimap-wrap { position: relative; width: 150px; height: 150px; border-radius: 50%; overflow: hidden; border: 1px solid rgba(255,224,151,0.24); background: radial-gradient(circle at 50% 50%, rgba(20,30,41,0.85), rgba(7,11,19,0.95)); }
#minimap { width: 100%; height: 100%; display: block; }
.map-n { position: absolute; top: 7px; left: 50%; transform: translateX(-50%); font-size: 0.47rem; letter-spacing: 0.15em; color: var(--gold); }
.map-caption { position: absolute; bottom: 11px; left: 50%; transform: translateX(-50%); font-size: 0.4rem; letter-spacing: 0.12em; white-space: nowrap; color: rgba(255,248,231,0.55); }
.hud-buttons { display: flex; flex-direction: column; gap: 7px; }
.hud-btn { width: 61px; height: 43px; border: 1px solid var(--line); background: rgba(9,14,25,0.64); backdrop-filter: blur(12px); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; border-radius: 2px; transition: 0.18s; }
.hud-btn span { color: var(--gold); font-size: 0.84rem; line-height: 1; }
.hud-btn b { font-size: 0.38rem; letter-spacing: 0.14em; font-weight: 500; color: rgba(255,248,231,0.55); }
.hud-btn:hover { border-color: var(--line-strong); background: rgba(22,32,50,0.8); }
.hud-bottom { position: absolute; bottom: 0; left: 0; right: 0; padding: 0 28px 20px; display: flex; justify-content: space-between; align-items: flex-end; gap: 20px; }
.party-dock { display: flex; gap: 7px; align-items: flex-end; }
.party-pill { width: 96px; height: 52px; display: flex; align-items: center; gap: 8px; padding: 6px 8px; background: linear-gradient(120deg, rgba(13,20,34,0.85), rgba(9,13,22,0.7)); border: 1px solid var(--line); position: relative; overflow: hidden; border-radius: 2px; transition: 0.2s; }
.party-pill.active { border-color: var(--bc, var(--gold)); }
.party-pill .orb { flex: 0 0 30px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font-size: 0.8rem; color: var(--bc); background: radial-gradient(circle at 36% 32%, color-mix(in srgb, var(--bc) 50%, #fff), color-mix(in srgb, var(--bc) 25%, #10182a) 64%, #070b14); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bc) 30%, transparent); }
.party-pill b { display: block; font-size: 0.52rem; font-weight: 600; letter-spacing: 0.04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 50px; }
.party-pill span { display: block; font-size: 0.4rem; color: rgba(255,248,231,0.48); margin-top: 2px; }
.party-pill .mini-hp { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: rgba(255,255,255,0.1); }
.party-pill .mini-hp i { display: block; height: 100%; background: var(--ok); transition: width 0.3s; }
.party-pill.fainted { opacity: 0.42; filter: grayscale(0.8); }
.control-hints { display: flex; gap: 14px; font-size: 0.48rem; letter-spacing: 0.1em; color: rgba(255,248,231,0.37); text-transform: uppercase; padding-bottom: 4px; }
.control-hints b { color: rgba(255,224,151,0.7); font-weight: 600; }
.save-state { font-size: 0.43rem; letter-spacing: 0.18em; color: rgba(120,228,162,0.55); padding-bottom: 5px; transition: opacity 0.4s; }
.save-state.saving { color: var(--gold); }
#interact-prompt { position: absolute; left: 50%; bottom: 17%; transform: translateX(-50%); display: flex; align-items: center; gap: 12px; padding: 9px 17px 9px 10px; background: rgba(8,13,23,0.82); border: 1px solid var(--line-strong); backdrop-filter: blur(14px); border-radius: 2px; animation: promptIn 0.25s ease both; pointer-events: none; }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }
.keycap { min-width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--gold); color: var(--gold); font-family: var(--serif); font-size: 0.9rem; background: rgba(242,201,109,0.08); }
#interact-prompt b { display: block; font-size: 0.68rem; letter-spacing: 0.06em; }
#interact-prompt span:last-child { display: block; margin-top: 2px; font-size: 0.5rem; letter-spacing: 0.12em; color: var(--muted); text-transform: uppercase; }
#toast-stack { position: absolute; top: 20%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 8px; pointer-events: none; width: min(400px, 80vw); }
.toast { padding: 9px 17px; background: rgba(8,13,23,0.88); border: 1px solid var(--line); backdrop-filter: blur(12px); font-size: 0.68rem; letter-spacing: 0.04em; color: var(--cream); display: flex; align-items: center; gap: 9px; animation: toastIn 0.3s ease both; box-shadow: 0 8px 30px rgba(0,0,0,0.3); }
.toast.out { animation: toastOut 0.4s ease both; }
.toast .t-icon { color: var(--gold); font-size: 0.8rem; }
.toast.good { border-color: rgba(120,228,162,0.4); }
.toast.bad { border-color: rgba(255,118,107,0.4); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }
#waypoint-arrow { position: absolute; left: 50%; bottom: 13%; width: 56px; height: 56px; margin-left: -28px; display: grid; place-items: center; pointer-events: none; color: var(--gold); text-shadow: 0 0 15px rgba(242,201,109,0.8); font-size: 1.2rem; }

/* dialogue */
#dialogue { position: absolute; z-index: 40; left: 50%; bottom: 13%; transform: translateX(-50%); width: min(900px, 90vw); display: flex; gap: 18px; padding: 19px 50px 19px 20px; background: linear-gradient(110deg, rgba(10,15,27,0.95), rgba(13,20,35,0.9)); border: 1px solid var(--line-strong); box-shadow: 0 30px 90px rgba(0,0,0,0.55); backdrop-filter: blur(20px); animation: promptIn 0.3s ease both; }
.dialogue-portrait { flex: 0 0 68px; width: 68px; height: 68px; border-radius: 50%; display: grid; place-items: center; background: radial-gradient(circle at 34% 30%, #38536b, #1a2639); border: 1px solid var(--gold); font-family: var(--serif); font-size: 1.5rem; color: var(--gold-2); }
.dialogue-body { flex: 1; }
.dialogue-meta { display: flex; align-items: baseline; gap: 10px; }
.dialogue-meta strong { font-family: var(--serif); font-size: 1.05rem; letter-spacing: 0.03em; }
.dialogue-meta span { font-size: 0.5rem; letter-spacing: 0.17em; color: var(--gold); text-transform: uppercase; }
#dialogue-text { margin: 7px 0 0; min-height: 38px; font-size: 0.83rem; line-height: 1.65; color: rgba(255,248,231,0.76); font-weight: 300; }
#dialogue-actions { display: flex; gap: 8px; margin-top: 10px; }
#dialogue-actions button { min-height: 34px; padding: 0 15px; border: 1px solid var(--line); background: rgba(255,255,255,0.04); font-size: 0.58rem; letter-spacing: 0.12em; text-transform: uppercase; }
#dialogue-actions button:hover { border-color: var(--gold); color: var(--gold); }
.dialogue-close { position: absolute; top: 11px; right: 14px; border: 0; background: transparent; color: rgba(255,255,255,0.35); font-size: 1.2rem; }

/* mobile controls */
#mobile-controls { display: none; position: absolute; inset: 0; pointer-events: none; z-index: 13; }
#joystick { position: absolute; left: 22px; bottom: 28px; width: 118px; height: 118px; border: 1px solid rgba(255,255,255,0.18); border-radius: 50%; background: rgba(8,13,23,0.34); backdrop-filter: blur(6px); pointer-events: auto; touch-action: none; }
#joystick-knob { position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255,240,195,0.9), rgba(212,168,69,0.72)); box-shadow: 0 4px 20px rgba(0,0,0,0.35); }
.mobile-actions { position: absolute; right: 22px; bottom: 30px; display: flex; align-items: flex-end; gap: 12px; pointer-events: auto; }
.round-btn { width: 64px; height: 64px; border-radius: 50%; border: 1px solid var(--line-strong); background: rgba(9,14,25,0.7); color: var(--gold-2); font-family: var(--serif); font-size: 1.1rem; backdrop-filter: blur(8px); }
.round-btn.small { width: 48px; height: 48px; font-size: 0.9rem; }

/* ---------- modals ---------- */
#modal-layer { position: absolute; inset: 0; z-index: 50; background: rgba(3,6,11,0.64); backdrop-filter: blur(7px); display: flex; align-items: center; justify-content: center; padding: 20px; }
.modal-shell { width: min(1120px, 95vw); max-height: 90vh; overflow-y: auto; background: linear-gradient(150deg, rgba(16,24,41,0.98), rgba(7,11,20,0.98)); border: 1px solid var(--line-strong); box-shadow: 0 40px 120px rgba(0,0,0,0.65); position: relative; animation: modalIn 0.28s cubic-bezier(.2,.9,.25,1) both; }
.modal-shell::-webkit-scrollbar { width: 5px; }
.modal-shell::-webkit-scrollbar-thumb { background: rgba(255,224,151,0.25); }
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(0.985); } to { opacity: 1; transform: none; } }
.modal-head { position: sticky; top: 0; z-index: 2; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; padding: 24px 30px 18px; background: linear-gradient(180deg, rgba(16,24,41,0.99), rgba(16,24,41,0.88) 80%, transparent); }
.modal-head h2 { margin: 7px 0 0; font-family: var(--serif); font-size: 1.8rem; font-weight: 500; letter-spacing: 0.03em; }
.modal-head p { margin: 7px 0 0; font-size: 0.7rem; color: var(--muted); }
.modal-close { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line); background: rgba(5,9,17,0.5); font-size: 1rem; flex: 0 0 auto; }
.modal-close:hover { border-color: var(--gold); color: var(--gold); }
.modal-body { padding: 0 30px 30px; }

/* atlas */
.atlas-tabs, .journal-tabs { display: flex; gap: 5px; border-bottom: 1px solid var(--line); margin-bottom: 20px; }
.tab-btn { border: 0; border-bottom: 2px solid transparent; background: transparent; padding: 9px 14px; font-size: 0.6rem; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(255,248,231,0.46); }
.tab-btn.active { color: var(--gold-2); border-bottom-color: var(--gold); }
.atlas-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.region-card { position: relative; min-height: 190px; border: 1px solid var(--line); background: linear-gradient(165deg, rgba(18,27,44,0.9), rgba(7,11,20,0.95)); overflow: hidden; padding: 16px; text-align: left; transition: 0.24s; }
.region-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 70% 0%, color-mix(in srgb, var(--rc) 26%, transparent), transparent 65%); opacity: 0.8; }
.region-card::after { content: ''; position: absolute; inset: 0; border: 1px solid transparent; transition: 0.2s; }
.region-card:hover { transform: translateY(-4px); }
.region-card:hover::after { border-color: var(--rc); }
.region-card.current::after { border-color: var(--gold); }
.region-card.cleared::before { background: radial-gradient(circle at 70% 0%, color-mix(in srgb, var(--gold) 30%, transparent), transparent 68%); }
.region-card > * { position: relative; z-index: 1; }
.rc-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 22px; }
.rc-num { font-family: var(--serif); font-size: 0.9rem; color: var(--rc); }
.rc-type { font-size: 0.46rem; letter-spacing: 0.16em; text-transform: uppercase; color: var(--rc); border: 1px solid color-mix(in srgb, var(--rc) 40%, transparent); padding: 3px 6px; }
.region-card h3 { margin: 0; font-family: var(--serif); font-size: 1.12rem; font-weight: 500; letter-spacing: 0.03em; }
.region-card p { margin: 5px 0 0; font-size: 0.6rem; line-height: 1.5; color: rgba(255,248,231,0.5); min-height: 27px; }
.rc-meta { display: flex; justify-content: space-between; align-items: center; margin-top: 17px; padding-top: 10px; border-top: 1px solid var(--line); font-size: 0.49rem; letter-spacing: 0.09em; color: rgba(255,248,231,0.42); }
.rc-badge { display: flex; align-items: center; gap: 5px; color: var(--gold); }
.rc-badge.locked { color: rgba(255,255,255,0.24); }
.rc-cta { margin-top: 11px; font-size: 0.5rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--rc); }
.atlas-note { margin-top: 16px; font-size: 0.58rem; color: rgba(255,248,231,0.4); display: flex; justify-content: space-between; }

/* journal */
.journal-tabs { margin-bottom: 18px; }
.journal-title { margin: 0 0 15px; font-family: var(--serif); font-size: 1.3rem; font-weight: 500; }
.inv-strip { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 18px; }
.ing-chip { display: flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--line); background: rgba(255,255,255,0.035); font-size: 0.58rem; }
.ing-chip b { color: var(--gold-2); font-weight: 500; }
.ing-chip span:first-child { font-size: 0.8rem; }
.craft-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 11px; }
.craft-card { padding: 15px; border: 1px solid var(--line); background: linear-gradient(155deg, rgba(20,30,48,0.72), rgba(7,11,20,0.85)); display: flex; flex-direction: column; min-height: 196px; }
.craft-icon { font-size: 1.7rem; margin-bottom: 8px; filter: drop-shadow(0 0 10px rgba(255,200,100,0.25)); }
.craft-card h4 { margin: 0; font-family: var(--serif); font-size: 1rem; font-weight: 500; }
.craft-card .craft-type { font-size: 0.46rem; letter-spacing: 0.16em; text-transform: uppercase; color: var(--tc); margin-top: 3px; }
.craft-card p { margin: 8px 0 10px; font-size: 0.61rem; line-height: 1.5; color: rgba(255,248,231,0.5); flex: 1; }
.recipe-line { display: flex; justify-content: space-between; font-size: 0.5rem; color: rgba(255,248,231,0.5); border-top: 1px solid var(--line); padding-top: 8px; margin-bottom: 8px; }
.recipe-line b { color: var(--gold); font-weight: 500; }
.craft-btn { min-height: 33px; border: 1px solid color-mix(in srgb, var(--tc) 45%, transparent); background: color-mix(in srgb, var(--tc) 9%, transparent); color: var(--tc); font-size: 0.54rem; letter-spacing: 0.13em; text-transform: uppercase; }
.craft-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--tc) 18%, transparent); }
.craft-btn:disabled { opacity: 0.32; cursor: default; }
.bag-summary { display: flex; gap: 14px; margin-bottom: 16px; }
.bag-stat { flex: 1; padding: 12px; border: 1px solid var(--line); background: rgba(255,255,255,0.025); }
.bag-stat span { display: block; font-size: 0.48rem; letter-spacing: 0.17em; text-transform: uppercase; color: var(--muted); }
.bag-stat b { display: block; margin-top: 3px; font-family: var(--serif); font-size: 1.3rem; font-weight: 500; color: var(--gold-2); }
.party-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 11px; }
.party-card { border: 1px solid var(--line); background: linear-gradient(150deg, rgba(19,29,47,0.72), rgba(7,11,20,0.82)); padding: 14px; display: grid; grid-template-columns: 48px 1fr; gap: 12px; }
.party-orb { width: 46px; height: 46px; border-radius: 50%; display: grid; place-items: center; background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--pc) 60%, #fff), color-mix(in srgb, var(--pc) 20%, #10182a) 65%, #070b14); color: var(--pc); font-size: 1rem; border: 1px solid color-mix(in srgb, var(--pc) 35%, transparent); }
.party-card h4 { margin: 0; font-family: var(--serif); font-size: 1.03rem; font-weight: 500; }
.party-card .pc-meta { font-size: 0.47rem; letter-spacing: 0.13em; text-transform: uppercase; color: var(--pc); margin-top: 2px; }
.pc-hp { height: 4px; margin-top: 8px; background: rgba(255,255,255,0.09); }
.pc-hp i { display: block; height: 100%; background: var(--ok); }
.pc-info { display: flex; justify-content: space-between; font-size: 0.48rem; color: var(--muted); margin-top: 4px; }
.pc-moves { grid-column: 1 / -1; display: flex; gap: 5px; flex-wrap: wrap; border-top: 1px solid var(--line); padding-top: 8px; margin-top: 2px; }
.pc-move { font-size: 0.46rem; padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--mc) 35%, transparent); color: var(--mc); }
.pc-actions { grid-column: 1 / -1; display: flex; gap: 6px; }
.mini-btn { flex: 1; min-height: 28px; border: 1px solid var(--line); background: rgba(255,255,255,0.03); font-size: 0.48rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
.mini-btn:hover { color: var(--gold); border-color: var(--gold); }
.empty-note { padding: 24px; text-align: center; color: var(--muted); font-size: 0.7rem; border: 1px dashed var(--line); }
.reserve-list { display: grid; grid-template-columns: repeat(3,1fr); gap: 9px; margin-top: 18px; }
.reserve-card { padding: 10px; border: 1px solid var(--line); background: rgba(255,255,255,0.025); display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.reserve-card b { display: block; font-size: 0.63rem; }
.reserve-card span { font-size: 0.48rem; color: var(--muted); }
.codex-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 9px; }
.codex-card { padding: 12px; border: 1px solid var(--line); background: rgba(255,255,255,0.025); min-height: 105px; }
.codex-card.seen { border-color: color-mix(in srgb, var(--cc) 30%, transparent); background: radial-gradient(circle at 70% 0%, color-mix(in srgb, var(--cc) 10%, transparent), transparent 70%), rgba(255,255,255,0.02); }
.codex-card h4 { margin: 0; font-family: var(--serif); font-size: 0.8rem; font-weight: 500; }
.codex-card span { font-size: 0.45rem; letter-spacing: 0.1em; color: var(--cc); text-transform: uppercase; }
.codex-card p { font-size: 0.5rem; color: var(--muted); margin: 6px 0 0; line-height: 1.45; }
.empty-codex { opacity: 0.25; }

/* ---------- battle ---------- */
#battle-ui { position: absolute; inset: 0; z-index: 30; pointer-events: none; }
#battle-ui > * { pointer-events: none; }
#battle-ui button, #battle-ui .battle-command, #battle-ui .treat-card, #battle-ui .result-card { pointer-events: auto; }
.battle-vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 45%, transparent 38%, rgba(4,6,12,0.45) 100%), linear-gradient(0deg, rgba(4,6,12,0.72), transparent 34%, transparent 76%, rgba(4,6,12,0.3)); }
.battle-top { position: absolute; top: 24px; left: 28px; right: 28px; display: flex; align-items: center; gap: 18px; }
.battle-region { font-size: 0.55rem; letter-spacing: 0.22em; color: rgba(255,248,231,0.55); }
.battle-round { display: flex; align-items: center; gap: 7px; margin-left: auto; padding: 6px 12px; border: 1px solid var(--line); background: rgba(8,13,23,0.55); }
.battle-round span { font-size: 0.46rem; letter-spacing: 0.16em; color: var(--muted); }
.battle-round b { color: var(--gold); font-family: var(--serif); font-size: 0.88rem; }
#battle-sound { margin-left: 4px; }
.battle-panel { position: absolute; min-width: 292px; padding: 14px 18px; background: linear-gradient(110deg, rgba(10,15,27,0.9), rgba(10,15,27,0.55)); border: 1px solid var(--line); backdrop-filter: blur(14px); }
.enemy-panel { top: 79px; left: 28px; animation: slideLeft 0.5s ease both; }
.player-panel { bottom: 190px; right: 28px; animation: slideRight 0.5s ease both; }
@keyframes slideLeft { from { opacity: 0; transform: translateX(-20px); } }
@keyframes slideRight { from { opacity: 0; transform: translateX(20px); } }
.combat-name { display: flex; align-items: center; gap: 8px; }
.combat-name span { color: var(--gold); font-size: 0.78rem; }
.combat-name strong { font-family: var(--serif); font-size: 1.03rem; letter-spacing: 0.04em; font-weight: 500; }
.combat-name i { margin-left: auto; font-style: normal; font-size: 0.48rem; letter-spacing: 0.13em; color: var(--muted); }
.hp-track { height: 6px; background: rgba(255,255,255,0.1); margin-top: 10px; overflow: hidden; }
.hp-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #ffb24f, #ff715b); transition: width 0.55s cubic-bezier(.2,.8,.2,1); box-shadow: 0 0 12px rgba(255,113,91,0.35); }
.hp-fill.player { background: linear-gradient(90deg, #70e6a1, #b7f98a); box-shadow: 0 0 12px rgba(112,230,161,0.35); }
.hp-meta { display: flex; justify-content: space-between; margin-top: 5px; font-size: 0.49rem; color: var(--muted); letter-spacing: 0.06em; }
#enemy-status, #player-status { color: var(--gold); }
.team-pips { display: flex; gap: 4px; margin-top: 8px; }
.team-pips i { width: 13px; height: 3px; background: rgba(255,255,255,0.15); }
.team-pips i.alive { background: var(--gold); }
.team-pips i.fainted { background: rgba(255,255,255,0.1); }
.focus-row { display: flex; align-items: center; gap: 8px; margin-top: 9px; }
.focus-row > span { font-size: 0.43rem; letter-spacing: 0.15em; color: var(--muted); }
.focus-pips { display: flex; gap: 3px; flex: 1; }
.focus-pips i { flex: 1; height: 3px; background: rgba(255,255,255,0.12); }
.focus-pips i.on { background: linear-gradient(90deg, #6bcedf, #b5f4e7); box-shadow: 0 0 6px rgba(115,234,210,0.5); }
.battle-feed { position: absolute; left: 28px; bottom: 190px; width: min(390px, 33vw); display: flex; flex-direction: column-reverse; gap: 5px; min-height: 56px; }
.feed-line { font-size: 0.65rem; line-height: 1.45; color: rgba(255,248,231,0.75); padding: 6px 10px; background: rgba(7,11,20,0.56); border-left: 1px solid var(--line); animation: toastIn 0.25s ease both; }
.feed-line b { color: var(--gold-2); font-weight: 500; }
.battle-command { position: absolute; right: 28px; bottom: 24px; width: 466px; padding: 15px 16px 14px; animation: commandIn 0.4s cubic-bezier(.2,.9,.25,1) both; }
@keyframes commandIn { from { opacity: 0; transform: translateY(16px); } }
.command-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.command-head span { font-size: 0.48rem; letter-spacing: 0.22em; color: var(--gold); }
.help-btn { width: 21px; height: 21px; border-radius: 50%; border: 1px solid var(--line); background: transparent; font-size: 0.56rem; color: var(--muted); }
.move-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.move-btn { text-align: left; min-height: 57px; border: 1px solid color-mix(in srgb, var(--mc) 28%, transparent); background: linear-gradient(120deg, color-mix(in srgb, var(--mc) 10%, rgba(8,13,23,0.8)), rgba(8,13,23,0.7)); padding: 8px 10px; transition: 0.16s; position: relative; overflow: hidden; }
.move-btn::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--mc); opacity: 0.6; }
.move-btn:hover:not(:disabled) { background: linear-gradient(120deg, color-mix(in srgb, var(--mc) 22%, rgba(8,13,23,0.8)), rgba(8,13,23,0.75)); border-color: var(--mc); }
.move-btn:disabled { opacity: 0.33; cursor: default; }
.move-btn .mv-top { display: flex; justify-content: space-between; gap: 7px; }
.move-btn b { font-size: 0.6rem; font-weight: 600; letter-spacing: 0.03em; }
.move-btn .mv-type { font-size: 0.39rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--mc); }
.move-btn .mv-bottom { display: flex; justify-content: space-between; margin-top: 5px; font-size: 0.42rem; color: var(--muted); }
.move-btn .mv-cost { color: var(--gold); }
.move-btn .mv-sig { color: var(--gold-2); }
.command-actions { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 6px; }
.command-actions button { min-height: 45px; border: 1px solid var(--line); background: rgba(255,255,255,0.035); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; transition: 0.16s; }
.command-actions button:hover { border-color: var(--line-strong); background: rgba(255,255,255,0.07); }
.command-actions button span { color: var(--gold); font-size: 0.73rem; line-height: 1; }
.command-actions button b { font-size: 0.43rem; letter-spacing: 0.11em; text-transform: uppercase; font-weight: 500; color: rgba(255,248,231,0.66); }
.command-actions button i { position: absolute; margin-left: 43px; margin-top: -14px; font-style: normal; font-size: 0.45rem; color: var(--gold); }
#treat-picker { position: absolute; right: 28px; bottom: 24px; width: 466px; padding: 17px; background: rgba(9,14,25,0.96); border: 1px solid var(--line-strong); box-shadow: var(--shadow); backdrop-filter: blur(20px); animation: commandIn 0.25s ease both; }
.treat-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.treat-head h4 { margin: 0; font-family: var(--serif); font-size: 1.02rem; font-weight: 500; }
.treat-head button { border: 0; background: transparent; color: var(--muted); font-size: 1rem; }
.treat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; max-height: 260px; overflow-y: auto; }
.treat-card { text-align: left; padding: 10px; border: 1px solid var(--line); background: rgba(255,255,255,0.03); }
.treat-card:hover { border-color: var(--tc); background: color-mix(in srgb, var(--tc) 9%, transparent); }
.treat-card .tc-top { display: flex; justify-content: space-between; align-items: center; }
.treat-card b { font-size: 0.63rem; }
.treat-card .tc-count { font-size: 0.54rem; color: var(--gold); }
.treat-card .tc-type { font-size: 0.42rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--tc); margin-top: 3px; }
.treat-card .tc-rate { font-size: 0.45rem; color: var(--ok); margin-top: 5px; }
.treat-card .tc-fav { color: var(--gold-2); }
#battle-result { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(3,6,11,0.5); backdrop-filter: blur(4px); }
.result-card { width: min(560px, 88vw); background: linear-gradient(150deg, rgba(17,26,44,0.98), rgba(7,11,20,0.98)); border: 1px solid var(--line-strong); box-shadow: 0 40px 120px rgba(0,0,0,0.7); padding: 32px; text-align: center; animation: modalIn 0.35s ease both; }
.result-sigil { font-size: 2.4rem; color: var(--gold); text-shadow: 0 0 30px rgba(242,201,109,0.6); }
.result-card h2 { margin: 10px 0 4px; font-family: var(--serif); font-size: 2.2rem; font-weight: 500; }
.result-card .result-sub { font-size: 0.65rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--gold); }
.result-stats { display: flex; justify-content: center; gap: 25px; margin: 25px 0; padding: 17px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.result-stats div span { display: block; font-size: 0.47rem; letter-spacing: 0.16em; color: var(--muted); text-transform: uppercase; }
.result-stats div b { display: block; margin-top: 4px; font-family: var(--serif); font-size: 1.3rem; font-weight: 500; color: var(--gold-2); }
.result-copy { font-size: 0.7rem; color: rgba(255,248,231,0.62); line-height: 1.65; margin: 0 0 22px; }
.result-actions { display: flex; justify-content: center; gap: 10px; }
#battle-tooltip { position: absolute; left: 50%; bottom: 215px; transform: translateX(-50%); max-width: 440px; padding: 11px 16px; font-size: 0.62rem; line-height: 1.55; background: rgba(8,13,23,0.96); border: 1px solid var(--line); }
.dmg-float { position: absolute; z-index: 35; font-family: var(--serif); font-weight: 700; font-size: 2.1rem; color: #fff1c4; text-shadow: 0 2px 15px rgba(0,0,0,0.75), 0 0 18px rgba(255,209,112,0.45); pointer-events: none; animation: dmgFloat 1.15s ease-out both; }
.dmg-float.crit { color: #ffd05e; font-size: 2.8rem; }
.dmg-float.heal { color: #8bf3ae; }
@keyframes dmgFloat { 0% { opacity: 0; transform: translate(-50%, 8px) scale(0.75); } 18% { opacity: 1; transform: translate(-50%, 0) scale(1.1); } 100% { opacity: 0; transform: translate(-50%, -55px) scale(0.92); } }
.shake { animation: shakeIt 0.42s ease; }
@keyframes shakeIt { 0%,100%{ transform: translate(0,0); } 20%{ transform: translate(-7px,4px); } 40%{ transform: translate(6px,-5px); } 60%{ transform: translate(-4px,-2px); } 80%{ transform: translate(3px,3px); } }

/* ---------- responsive ---------- */
@media (max-width: 1100px) {
  .hud-center { flex-direction: row; align-items: center; }
  .keeper-chip { display: none; }
  .control-hints { display: none; }
  .atlas-grid { grid-template-columns: repeat(2, 1fr); }
  .craft-grid { grid-template-columns: repeat(2, 1fr); }
  .codex-grid { grid-template-columns: repeat(3, 1fr); }
  .battle-feed { width: 280px; }
}
@media (max-width: 820px) {
  .title-main { top: 20%; left: 6vw; width: 86vw; }
  .game-title { font-size: clamp(4rem, 18vw, 7.5rem); }
  .title-sub { font-size: 0.82rem; }
  .title-stats { gap: 22px; }
  .title-topbar { padding: 20px 5vw; }
  .title-top-meta { display: none; }
  .title-footer { display: none; }
  .creator-panel { left: 4vw; right: 4vw; width: auto; top: auto; bottom: 2vh; transform: none; max-height: 54vh; padding: 22px; }
  .creator-layout { overflow-y: auto; }
  .creator-hint { display: none; }
  .creator-top { padding: 16px 4vw; }
  .step-dots { display: none; }
  .creator-panel h2 { font-size: 1.5rem; margin-bottom: 16px; }
  .creator-panel { background: rgba(8,13,23,0.94); }
  .starter-heading { top: 10%; left: 5vw; right: 5vw; }
