export class AudioEngine {
  constructor() {
    this.ctx = null
    this.enabled = true
    this.master = null
    this.ambient = null
    this.ambientGain = null
    this.notes = []
    this.region = null
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.enabled ? 0.42 : 0
    const comp = this.ctx.createDynamicsCompressor()
    comp.threshold.value = -24
    comp.ratio.value = 4
    this.master.connect(comp)
    comp.connect(this.ctx.destination)
    this.ambient = this.ctx.createGain()
    this.ambient.gain.value = 0.12
    this.ambient.connect(this.master)
    this.noiseBuffer = this.makeNoise(3)
    this.startWind()
  }

  makeNoise(seconds) {
    const rate = this.ctx.sampleRate
    const buffer = this.ctx.createBuffer(1, rate * seconds, rate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1
    return buffer
  }

  startWind() {
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.loop = true
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 420
    const gain = this.ctx.createGain()
    gain.gain.value = 0.022
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    src.start()
    this.wind = { src, filter, gain }
  }

  setEnabled(on) {
    this.enabled = on
    if (!this.ctx) return
    this.master.gain.cancelScheduledValues(this.ctx.currentTime)
    this.master.gain.linearRampToValueAtTime(on ? 0.42 : 0, this.ctx.currentTime + 0.15)
  }

  toggle() {
    this.setEnabled(!this.enabled)
    return this.enabled
  }

  chordFor(region) {
    switch (region) {
      case 'verdant': return [130.81, 196.0, 261.63, 329.63]
      case 'ember': return [98.0, 146.83, 196.0, 246.94]
      case 'tide': return [110.0, 164.81, 220.0, 293.66]
      case 'frost': return [123.47, 185.0, 246.94, 311.13]
      case 'sunken': return [92.5, 138.59, 185.0, 233.08]
      case 'storm': return [103.83, 155.56, 207.65, 261.63]
      case 'cinder': return [87.31, 130.81, 174.61, 220.0]
      case 'celestial': return [146.83, 220.0, 293.66, 369.99]
      default: return [110, 165, 220, 330]
    }
  }

  setRegion(region) {
    if (!this.ctx || this.region === region) return
    this.region = region
    if (!this.ambient) return
    const now = this.ctx.currentTime
    for (const n of this.notes) {
      n.gain.gain.cancelScheduledValues(now)
      n.gain.gain.linearRampToValueAtTime(0, now + 1.2)
      try { n.osc.stop(now + 1.3) } catch {}
    }
    this.notes = []
    const chord = this.chordFor(region)
    chord.forEach((f, i) => {
      const osc = this.ctx.createOscillator()
      const gain = this.ctx.createGain()
      const filter = this.ctx.createBiquadFilter()
      osc.type = i % 2 ? 'sine' : 'triangle'
      osc.frequency.value = f
      osc.detune.value = (i - 1.5) * 4
      filter.type = 'lowpass'
      filter.frequency.value = 600 + i * 180
      gain.gain.value = 0
      gain.gain.linearRampToValueAtTime(0.032 / (i * 0.5 + 1), now + 2)
      osc.connect(filter)
      filter.connect(gain)
      gain.connect(this.ambient)
      osc.start()
      this.notes.push({ osc, gain })
    })
  }

  tone(freq, dur = 0.12, type = 'sine', gain = 0.1, slide = 0) {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, now)
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), now + dur)
    g.gain.setValueAtTime(0.0001, now)
    g.gain.exponentialRampToValueAtTime(gain, now + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur)
    osc.connect(g)
    g.connect(this.master)
    osc.start(now)
    osc.stop(now + dur + 0.02)
  }

  noise(dur = 0.2, freq = 900, gain = 0.12) {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.setValueAtTime(freq, now)
    filter.Q.value = 0.9
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(now)
    src.stop(now + dur + 0.02)
  }

  click() { this.tone(660, 0.07, 'triangle', 0.05) }
  select() { this.tone(520, 0.08, 'sine', 0.06); setTimeout(() => this.tone(780, 0.1, 'sine', 0.04), 60) }
  hit(heavy = false) {
    this.noise(heavy ? 0.35 : 0.2, heavy ? 380 : 850, heavy ? 0.18 : 0.12)
    this.tone(heavy ? 90 : 150, heavy ? 0.28 : 0.16, 'sawtooth', 0.08, -40)
  }
  special() {
    this.tone(440, 0.2, 'sine', 0.07, 320)
    setTimeout(() => this.tone(660, 0.25, 'triangle', 0.055, 280), 80)
  }
  capture() {
    const seq = [523, 659, 784, 1046]
    seq.forEach((f, i) => setTimeout(() => this.tone(f, 0.22, 'sine', 0.08), i * 95))
  }
  levelUp() {
    const seq = [392, 523, 659, 784, 1046]
    seq.forEach((f, i) => setTimeout(() => this.tone(f, 0.3, 'triangle', 0.075), i * 110))
  }
  badge() {
    const seq = [261, 329, 392, 523, 659]
    seq.forEach((f, i) => setTimeout(() => this.tone(f, 0.5, 'sine', 0.1), i * 130))
  }
  error() { this.tone(140, 0.18, 'square', 0.05, -20) }
  whoosh() { this.noise(0.35, 1600, 0.08) }
}

import * as THREE from 'three'
import {
  MOVES, SPECIES, TYPES, TREATS, typeMultiplier, statsFor, movesFor, xpToNext,
  makeCreature, regionById
} from './data.js'
import { buildCreature, makeGlowTexture } from './art.js'
import { makeBattleArena } from './world.js'

const $ = (id) => document.getElementById(id)
const delay = (ms) => new Promise(r => setTimeout(r, ms))
const clamp = (v, a, b) => Math.min(b, Math.max(a, v))
const ease = (t) => 1 - Math.pow(1 - t, 3)

export class Battle {
  constructor(game, config) {
    this.game = game
    this.config = config
    this.region = regionById(config.regionId || game.state.player.regionId)
    this.isGym = config.type === 'gym'
    this.abort = new AbortController()
    this.effects = []
    this.phase = 'intro'
    this.round = 1
    this.busy = false
    this.focus = 8
    this.maxFocus = 10
    this.shake = 0
    this.turnCount = 0
    this.playerStatuses = []
    this.enemyStatuses = []
    this.levelUps = []
    this.logLines = []
    this.tempPick = null

    const party = game.state.player.party
    this.activeIdx = party.findIndex(c => c.hp > 0)
    if (this.activeIdx < 0) this.activeIdx = 0
    this.playerCreature = party[this.activeIdx]
    game.state.player.activeIndex = this.activeIdx

    if (config.type === 'wild') {
      const w = config.wild
      const st = statsFor(SPECIES[w.speciesId], w.level)
      this.enemyTeam = [{ speciesId: w.speciesId, level: w.level, hp: st.hp, maxHp: st.hp, statuses: [] }]
      this.wild = w
    } else {
      this.enemyTeam = config.gym.team.map(m => {
        const st = statsFor(SPECIES[m.species], m.level)
        return { speciesId: m.species, level: m.level, hp: st.hp, maxHp: st.hp, statuses: [] }
      })
      this.gym = config.gym
    }
    this.enemyIdx = 0
    this.enemy = this.enemyTeam[0]
    this.arena = makeBattleArena(this.region)
    this.playerModel = null
    this.enemyModel = null
    this.buildModels()
    this.bindUI()
    game.enterBattleMode(this)
    game.showBattleUI(true)
    this.setupUI()
    this.log(`A wild ${this.enemyName()} appeared!`, false)
    if (this.isGym) this.log(`<b>${this.gym.leader}</b> sends out ${this.enemyName()}!`, false)
    this.renderMoves()
    this.updateUI()
    this.phase = 'select'
    setTimeout(() => { if (!this.destroyed) this.updateUI() }, 50)
  }

  enemyName() { return SPECIES[this.enemy.speciesId].name }

  buildModels() {
    if (this.playerModel) {
      this.arena.scene.remove(this.playerModel)
      this.playerModel = null
    }
    if (this.enemyModel) {
      this.arena.scene.remove(this.enemyModel)
      this.enemyModel = null
    }
    this.pBase = new THREE.Vector3(-5.2, 0.05, 2.2)
    this.eBase = new THREE.Vector3(5.0, 0.05, -2.2)
    this.playerModel = buildCreature(this.playerCreature.speciesId, { aura: true })
    this.playerModel.position.copy(this.pBase)
    this.playerModel.lookAt(this.eBase.x, 0, this.eBase.z)
    this.arena.scene.add(this.playerModel)

    this.enemyModel = buildCreature(this.enemy.speciesId, { aura: true })
    this.enemyModel.position.copy(this.eBase)
    this.enemyModel.lookAt(this.pBase.x, 0, this.pBase.z)
    this.arena.scene.add(this.enemyModel)

    const pGlow = new THREE.PointLight(TYPES[SPECIES[this.playerCreature.speciesId].type].color, 6, 14, 2)
    pGlow.position.set(-4, 3, 2)
    this.arena.scene.add(pGlow)
    this.pGlow = pGlow
    const eGlow = new THREE.PointLight(TYPES[SPECIES[this.enemy.speciesId].type].color, 6, 14, 2)
    eGlow.position.set(4, 3, -2)
    this.arena.scene.add(eGlow)
    this.eGlow = eGlow
  }

  bindUI() {
    const signal = this.abort.signal
    $('move-grid').addEventListener('click', (e) => {
      const b = e.target.closest('[data-move]')
      if (b) this.useMove(b.dataset.move)
    }, { signal })
    $('btn-capture').addEventListener('click', () => this.openTreatPicker(), { signal })
    $('btn-swap').addEventListener('click', () => this.openSwapPicker(), { signal })
    $('btn-brace').addEventListener('click', () => this.brace(), { signal })
    $('btn-run').addEventListener('click', () => this.tryFlee(), { signal })
    $('battle-help').addEventListener('click', () => this.showHelp(), { signal })
    $('battle-sound').addEventListener('click', () => { this.game.audio.toggle(); this.game.toast(this.game.audio.enabled ? 'Sound on' : 'Sound muted', '♪') }, { signal })
  }

  setupUI() {
    const el = $('battle-region')
    el.textContent = `${this.region.name.toUpperCase()} · ${this.isGym ? 'GYM BATTLE' : 'WILD ENCOUNTER'}`
    $('battle-turn').textContent = '1'
    $('battle-feed').innerHTML = ''
    this.logLines = []
    $('battle-result').classList.add('hidden')
    $('battle-result').innerHTML = ''
    $('treat-picker').classList.add('hidden')
    $('battle-command').classList.remove('hidden')
    $('enemy-panel').style.opacity = '1'
    $('player-panel').style.opacity = '1'
    const enemyType = TYPES[SPECIES[this.enemy.speciesId].type]
    $('enemy-panel').style.borderColor = enemyType.color + '55'
    $('player-panel').style.borderColor = TYPES[SPECIES[this.playerCreature.speciesId].type].color + '55'
    $('enemy-type-icon').textContent = enemyType.icon
    $('enemy-type-icon').style.color = enemyType.color
    $('player-type-icon').textContent = TYPES[SPECIES[this.playerCreature.speciesId].type].icon
    $('player-type-icon').style.color = TYPES[SPECIES[this.playerCreature.speciesId].type].color
    $('enemy-name').textContent = SPECIES[this.enemy.speciesId].name
    $('enemy-level').textContent = `LV ${this.enemy.level}`
    $('player-battle-name').textContent = SPECIES[this.playerCreature.speciesId].name
    $('player-level').textContent = `LV ${this.playerCreature.level}`
    this.renderMoves()
    this.updateTeamPips()
    this.updateUI()
  }

  renderMoves() {
    const grid = $('move-grid')
    const moves = movesFor(SPECIES[this.playerCreature.speciesId], this.playerCreature.level)
    grid.innerHTML = ''
    for (const id of moves) {
      const m = MOVES[id]
      const t = TYPES[m.type]
      const btn = document.createElement('button')
      btn.className = 'move-btn'
      btn.dataset.move = id
      btn.style.setProperty('--mc', t.color)
      btn.disabled = this.phase !== 'select' || this.focus < m.cost
      btn.innerHTML = `
        <div class="mv-top"><b>${m.name}</b><span class="mv-type">${t.name}</span></div>
        <div class="mv-bottom"><span>${m.power ? 'PWR ' + m.power : m.heal ? 'MEND' : m.selfStatus ? 'BUFF' : 'SUPPORT'}</span><span class="mv-cost">${m.signature ? '✦ ' : ''}${m.cost} FOCUS</span></div>`
      grid.appendChild(btn)
    }
  }

  updateTeamPips() {
    const pips = $('enemy-team')
    pips.innerHTML = ''
    if (this.enemyTeam.length <= 1) { pips.style.display = 'none'; return }
    pips.style.display = 'flex'
    this.enemyTeam.forEach((e, i) => {
      const i2 = document.createElement('i')
      i2.className = e.hp > 0 ? (i === this.enemyIdx ? 'alive' : '') : 'fainted'
      pips.appendChild(i2)
    })
  }

  updateUI() {
    if (this.destroyed) return
    const pst = statsFor(SPECIES[this.playerCreature.speciesId], this.playerCreature.level)
    const est = statsFor(SPECIES[this.enemy.speciesId], this.enemy.level)
    $('enemy-hp').style.width = `${clamp(this.enemy.hp / this.enemy.maxHp * 100, 0, 100)}%`
    $('player-hp').style.width = `${clamp(this.playerCreature.hp / pst.hp * 100, 0, 100)}%`
    $('enemy-hp-text').textContent = `${Math.max(0, Math.round(this.enemy.hp))} / ${this.enemy.maxHp}`
    $('player-hp-text').textContent = `${Math.max(0, Math.round(this.playerCreature.hp))} / ${pst.hp}`
    $('player-hp').classList.toggle('low', this.playerCreature.hp / pst.hp < 0.25)
    $('battle-turn').textContent = String(this.round)
    $('enemy-level').textContent = `LV ${this.enemy.level}`
    $('player-level').textContent = `LV ${this.playerCreature.level}`
    $('enemy-name').textContent = SPECIES[this.enemy.speciesId].name
    $('player-battle-name').textContent = SPECIES[this.playerCreature.speciesId].name
    $('enemy-type-icon').textContent = TYPES[SPECIES[this.enemy.speciesId].type].icon
    $('enemy-type-icon').style.color = TYPES[SPECIES[this.enemy.speciesId].type].color
    $('player-type-icon').textContent = TYPES[SPECIES[this.playerCreature.speciesId].type].icon
    $('player-type-icon').style.color = TYPES[SPECIES[this.playerCreature.speciesId].type].color
    $('enemy-status').textContent = this.statusText(this.enemy.statuses)
    $('player-status').textContent = this.statusText(this.playerStatuses)
    const totalTreats = Object.values(this.game.state.player.treats).reduce((a, b) => a + b, 0)
    $('treat-count').textContent = totalTreats
    const pips = $('focus-pips')
    pips.innerHTML = ''
    for (let i = 0; i < this.maxFocus; i++) {
      const p = document.createElement('i')
      if (i < this.focus) p.className = 'on'
      pips.appendChild(p)
    }
    this.renderMoves()
    this.updateTeamPips()
    $('btn-capture').disabled = this.isGym
    $('btn-capture').style.opacity = this.isGym ? '0.35' : '1'
    $('btn-run').disabled = this.isGym
    $('btn-run').style.opacity = this.isGym ? '0.35' : '1'
  }

  statusText(statuses) {
    if (!statuses?.length) return ''
    return statuses.map(s => `${s.icon || ''} ${s.name || s.id}`.trim()).join(' · ')
  }

  addStatus(target, id, turns = 3) {
    const existing = target.find(s => s.id === id)
    if (existing) { existing.turns = Math.max(existing.turns, turns); return false }
    const meta = { scorch: { name: 'Scorched', icon: '♨' }, chill: { name: 'Chilled', icon: '❄' }, static: { name: 'Static', icon: 'ϟ' }, root: { name: 'Rooted', icon: '❧' }, guard: { name: 'Guarded', icon: '◈' }, fury: { name: 'Fury', icon: '⟡' }, haste: { name: 'Haste', icon: '»' } }[id]
    target.push({ id, turns, name: meta?.name || id, icon: meta?.icon || '•' })
    return true
  }

  hasStatus(list, id) { return list.some(s => s.id === id) }

  log(text, sound = true) {
    if (this.destroyed) return
    const feed = $('battle-feed')
    this.logLines.unshift({ text, time: performance.now() })
    const line = document.createElement('div')
    line.className = 'feed-line'
    line.innerHTML = text
    feed.prepend(line)
    while (feed.children.length > 4) feed.removeChild(feed.lastChild)
    if (sound) this.game.audio.click()
  }

  floatText(text, side, cls = '') {
    const el = document.createElement('div')
    el.className = `dmg-float ${cls}`
    el.textContent = text
    el.style.left = side === 'enemy' ? '62%' : '38%'
    el.style.top = `${30 + Math.random() * 8}%`
    $('battle-ui').appendChild(el)
    setTimeout(() => el.remove(), 1200)
  }

  burst(side, color) {
    const count = 26
    const pos = new Float32Array(count * 3)
    const vel = []
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 1.2
      pos[i * 3 + 1] = (Math.random() - 0.5) * 1.2
      pos[i * 3 + 2] = (Math.random() - 0.5) * 1.2
      vel.push(new THREE.Vector3((Math.random() - 0.5) * 7, Math.random() * 6, (Math.random() - 0.5) * 7))
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    const mat = new THREE.PointsMaterial({ color, size: 0.2, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending })
    const pts = new THREE.Points(geo, mat)
    const base = side === 'enemy' ? this.eBase : this.pBase
    pts.position.set(base.x, 2.5, base.z)
    this.arena.scene.add(pts)
    this.effects.push({ pts, vel, life: 0.9, max: 0.9 })
  }

  tween(duration, fn) {
    return new Promise(resolve => {
      const start = performance.now()
      const step = (now) => {
        const t = clamp((now - start) / duration, 0, 1)
        fn(ease(t), t)
        if (t < 1) requestAnimationFrame(step)
        else resolve()
      }
      requestAnimationFrame(step)
    })
  }

  async animateAttack(side) {
    const model = side === 'player' ? this.playerModel : this.enemyModel
    const base = side === 'player' ? this.pBase : this.eBase
    const dir = side === 'player' ? 1 : -1
    this.game.audio.whoosh()
    await this.tween(220, (e) => {
      model.position.x = base.x + dir * e * 1.4
      model.position.z = base.z + (side === 'player' ? -e * 0.4 : e * 0.4)
    })
    await this.tween(260, (e) => {
      model.position.x = base.x + dir * (1 - e) * 1.4
      model.position.z = base.z + (side === 'player' ? -1 : 1) * (1 - e) * 0.4
    })
  }

  async useMove(moveId) {
    if (this.phase !== 'select' || this.busy) return
    const move = MOVES[moveId]
    if (!move || this.focus < move.cost) { this.game.audio.error(); return }
    this.busy = true
    this.phase = 'busy'
    this.focus -= move.cost
    this.updateUI()
    this.log(`<b>${SPECIES[this.playerCreature.speciesId].name}</b> used ${move.name}!`)
    await this.animateAttack('player')
    await this.resolveMove('player', move)
    if (this.phase === 'done') return
    if (this.enemy.hp <= 0) {
      await this.handleEnemyKO()
      return
    }
    await delay(420)
    await this.enemyTurn()
    if (this.phase === 'done') return
    await this.endRound()
  }

  async resolveMove(side, move) {
    const isPlayer = side === 'player'
    const attacker = isPlayer ? this.playerCreature : this.enemy
    const attackerSpecies = SPECIES[attacker.speciesId]
    const defenderCreature = isPlayer ? this.enemy : this.playerCreature
    const defenderSpecies = SPECIES[defenderCreature.speciesId]
    const attackerStatuses = isPlayer ? this.playerStatuses : this.enemy.statuses
    const defenderStatuses = isPlayer ? this.enemy.statuses : this.playerStatuses
    const atkStats = statsFor(attackerSpecies, attacker.level)
    const defStats = statsFor(defenderSpecies, defenderCreature.level)
    const color = TYPES[move.type].color

    if (move.selfStatus) {
      const added = this.addStatus(attackerStatuses, move.selfStatus, 3)
      if (added) this.log(`${attackerSpecies.name} is now <b>${this.statusName(move.selfStatus)}</b>.`)
      this.burst(isPlayer ? 'player' : 'enemy', color)
      this.game.audio.special()
      return
    }
    if (move.heal) {
      const amount = Math.round(defStats.hp * move.heal)
      const max = isPlayer ? defStats.hp : this.enemy.maxHp
      if (isPlayer) this.playerCreature.hp = Math.min(defStats.hp, this.playerCreature.hp + amount)
      else this.enemy.hp = Math.min(this.enemy.maxHp, this.enemy.hp + amount)
      this.log(`${attackerSpecies.name} restored <b>${amount} HP</b>.`)
      this.floatText(`+${amount}`, isPlayer ? 'player' : 'enemy', 'heal')
      this.updateUI()
      this.game.audio.special()
      return
    }
    if (!move.power) return

    let atk = atkStats.atk
    if (this.hasStatus(attackerStatuses, 'chill')) atk *= 0.75
    if (this.hasStatus(attackerStatuses, 'fury')) atk *= 1.25
    let def = defStats.def
    if (this.hasStatus(defenderStatuses, 'guard')) def *= 1.32
    if (this.hasStatus(defenderStatuses, 'root')) def *= 0.74
    const stab = move.type === attackerSpecies.type ? 1.2 : 1
    const mult = typeMultiplier(move.type, defenderSpecies.type)
    const crit = Math.random() < 0.09
    let dmg = move.power * (0.21 + attacker.level * 0.0185) * (atk / Math.max(12, def)) * stab * mult
    dmg *= 0.9 + Math.random() * 0.18
    if (crit) dmg *= 1.55
    dmg = Math.max(1, Math.round(dmg))

    let defender = isPlayer ? this.playerCreature : this.enemy
    if (isPlayer) this.enemy.hp = Math.max(0, this.enemy.hp - dmg)
    else this.playerCreature.hp = Math.max(0, this.playerCreature.hp - dmg)

    this.burst(isPlayer ? 'enemy' : 'player', color)
    this.floatText(`${dmg}${crit ? '!' : ''}`, isPlayer ? 'enemy' : 'player', crit ? 'crit' : '')
    this.shake = crit ? 0.45 : 0.26
    this.game.audio.hit(crit || dmg > 35)
    $('flash').classList.add('on')
    setTimeout(() => $('flash').classList.remove('on'), 90)

    if (mult > 1.1) this.log(`It's <b>super effective</b>!`)
    else if (mult < 0.9) this.log(`It's not very effective…`)
    if (crit) this.log(`A critical strike!`)
    if (move.drain) {
      const heal = Math.round(dmg * move.drain)
      if (isPlayer) this.playerCreature.hp = Math.min(atkStats.hp, this.playerCreature.hp + heal)
      else this.enemy.hp = Math.min(this.enemy.maxHp, this.enemy.hp + heal)
      this.log(`${attackerSpecies.name} drained <b>${heal} HP</b>.`)
      this.floatText(`+${heal}`, isPlayer ? 'player' : 'enemy', 'heal')
    }
    if (move.status && Math.random() < move.status.chance) {
      const targetStatuses = isPlayer ? this.enemy.statuses : this.playerStatuses
      if (this.addStatus(targetStatuses, move.status.id, 3)) {
        this.log(`${defenderSpecies.name} is <b>${this.statusName(move.status.id)}</b>!`)
      }
    }
    this.updateUI()
  }

  statusName(id) {
    return { scorch: 'Scorched', chill: 'Chilled', static: 'Static', root: 'Rooted', guard: 'Guarded', fury: 'Fury', haste: 'Haste' }[id] || id
  }

  async enemyTurn() {
    if (this.enemy.hp <= 0) return
    if (this.hasStatus(this.enemy.statuses, 'static') && Math.random() < 0.3) {
      this.log(`${this.enemyName()} crackles with static and loses its turn!`)
      this.shake = 0.12
      return
    }
    const moves = movesFor(SPECIES[this.enemy.speciesId], this.enemy.level)
    let best = null
    let bestScore = -999
    const playerType = SPECIES[this.playerCreature.speciesId].type
    for (const id of moves) {
      const m = MOVES[id]
      if (!m.power && !m.selfStatus && !m.heal) continue
      let score = m.power * typeMultiplier(m.type, playerType)
      if (m.type === SPECIES[this.enemy.speciesId].type) score *= 1.15
      if (m.status) score += 18
      if (m.selfStatus) score += this.enemy.hp / this.enemy.maxHp < 0.6 ? 12 : 2
      if (m.heal) score += this.enemy.hp / this.enemy.maxHp < 0.45 ? 55 : 0
      score += Math.random() * 14
      if (score > bestScore) { bestScore = score; best = m }
    }
    if (!best) best = MOVES[moves[0]]
    this.log(`<b>${this.enemyName()}</b> used ${best.name}!`)
    await this.animateAttack('enemy')
    await this.resolveMove('enemy', best)
    if (this.playerCreature.hp <= 0) {
      await this.handlePlayerKO()
    }
  }

  async endRound() {
    if (this.phase === 'done') return
    this.round++
    this.focus = Math.min(this.maxFocus, this.focus + 2)

    for (const [side, statuses, creature] of [['player', this.playerStatuses, this.playerCreature], ['enemy', this.enemy.statuses, this.enemy]]) {
      if (side === 'player' && creature.hp <= 0) continue
      if (side === 'enemy' && this.enemy.hp <= 0) continue
      if (this.hasStatus(statuses, 'scorch')) {
        const max = statsFor(SPECIES[creature.speciesId], creature.level).hp
        const burn = Math.max(2, Math.round(max * 0.06))
        if (side === 'player') this.playerCreature.hp = Math.max(0, this.playerCreature.hp - burn)
        else this.enemy.hp = Math.max(0, this.enemy.hp - burn)
        this.log(`${side === 'player' ? SPECIES[this.playerCreature.speciesId].name : this.enemyName()} is seared for <b>${burn}</b> damage.`)
        this.floatText(`${burn}`, side, '')
        this.game.audio.hit(false)
      }
      statuses.forEach(s => { s.turns -= 1 })
      const expiring = statuses.filter(s => s.turns <= 0)
      statuses.splice(0, statuses.length, ...statuses.filter(s => s.turns > 0))
      for (const s of expiring) this.log(`${side === 'player' ? SPECIES[this.playerCreature.speciesId].name : this.enemyName()}'s ${s.name} faded.`)
    }
    this.updateUI()
    if (this.enemy.hp <= 0) { await this.handleEnemyKO(); return }
    if (this.playerCreature.hp <= 0) { await this.handlePlayerKO(); return }
    this.phase = 'select'
    this.busy = false
    this.updateUI()
  }

  async handleEnemyKO() {
    this.enemy.hp = 0
    this.updateUI()
    this.game.audio.badge()
    this.log(`<b>${this.enemyName()}</b> was defeated!`)
    if (this.enemyModel) {
      const model = this.enemyModel
      await this.tween(450, (e) => { model.scale.setScalar(1 - e * 0.35); model.position.y = this.eBase.y + e * 0.3 })
      model.visible = false
    }
    if (this.enemyIdx < this.enemyTeam.length - 1) {
      this.enemyIdx++
      this.enemy = this.enemyTeam[this.enemyIdx]
      this.enemyStatuses = []
      await delay(500)
      this.buildModels()
      this.log(`${this.gym?.leader || 'The keeper'} sends out <b>${this.enemyName()}</b>!`)
      this.updateUI()
      this.phase = 'select'
      this.busy = false
      return
    }
    await this.win()
  }

  async handlePlayerKO() {
    this.playerCreature.hp = 0
    this.updateUI()
    this.log(`<b>${SPECIES[this.playerCreature.speciesId].name}</b> fainted!`)
    this.game.audio.hit(true)
    const next = this.game.state.player.party.findIndex((c, i) => c.hp > 0 && i !== this.activeIdx)
    if (next < 0) {
      await delay(700)
      this.lose()
      return
    }
    this.activeIdx = next
    this.playerCreature = this.game.state.player.party[next]
    this.game.state.player.activeIndex = next
    this.playerStatuses = []
    this.focus = 8
    await delay(700)
    this.buildModels()
    this.log(`Go, <b>${SPECIES[this.playerCreature.speciesId].name}</b>!`)
    this.updateUI()
    this.phase = 'select'
    this.busy = false
  }

  async win() {
    this.phase = 'done'
    this.busy = true
    this.updateUI()
    const rewardXp = this.isGym
      ? Math.round(this.enemyTeam.reduce((a, e) => a + e.level, 0) * 9 + 40)
      : Math.round(this.enemy.level * 11 + 18)
    const levelUps = []
    for (const c of this.game.state.player.party) {
      if (c.hp <= 0) continue
      const gain = c === this.playerCreature ? rewardXp : Math.round(rewardXp * 0.45)
      const ups = this.grantXp(c, gain)
      levelUps.push(...ups.map(u => ({ creature: c, ...u })))
    }
    this.levelUps = levelUps
    let badge = null
    if (this.isGym) {
      badge = this.gym
      if (!this.game.state.player.badges.includes(this.region.id)) {
        this.game.state.player.badges.push(this.region.id)
      }
      const mats = this.gym.reward?.materials || {}
      for (const [k, v] of Object.entries(mats)) this.game.state.player.inventory[k] = (this.game.state.player.inventory[k] || 0) + v
      this.game.audio.badge()
    } else if (this.wild) {
      this.wild.active = false
      this.wild.root.visible = false
      this.wild.respawnAt = performance.now() + 45000
    }
    this.game.save()
    const extra = levelUps.length ? `${levelUps.length} level-up${levelUps.length > 1 ? 's' : ''}!` : ''
    this.showResult({
      win: true,
      title: this.isGym ? 'Sigil Earned' : 'Victory',
      sub: this.isGym ? `${this.gym.badge}` : 'The wilds grow quiet',
      xp: rewardXp,
      badge,
      levels: this.levelUps,
      copy: this.isGym
        ? `${this.gym.leader} bows their head. ${this.gym.quote}${extra ? ' ' + extra : ''}`
        : `Your bond deepens.${extra ? ' ' + extra : ''}`
    })
  }

  grantXp(creature, amount) {
    creature.xp += amount
    const ups = []
    while (creature.xp >= xpToNext(creature.level) && creature.level < 60) {
      const need = xpToNext(creature.level)
      creature.xp -= need
      const oldLevel = creature.level
      const oldStats = statsFor(SPECIES[creature.speciesId], oldLevel)
      creature.level++
      const newStats = statsFor(SPECIES[creature.speciesId], creature.level)
      creature.maxHp = newStats.hp
      creature.hp = Math.min(newStats.hp, creature.hp + (newStats.hp - oldStats.hp))
      const oldMoves = movesFor(SPECIES[creature.speciesId], oldLevel)
      const newMoves = movesFor(SPECIES[creature.speciesId], creature.level)
      const learned = newMoves.filter(m => !oldMoves.includes(m)).map(m => MOVES[m]?.name).filter(Boolean)
      ups.push({ from: oldLevel, to: creature.level, learned })
    }
    return ups
  }

  lose() {
    this.phase = 'done'
    this.busy = true
    this.game.audio.error()
    this.showResult({
      win: false, title: 'The Wilds Prevail', sub: 'Your party needs rest',
      xp: 0, copy: 'Everything goes dark for a moment. You wake at the waystone, your party tended and your resolve intact. The titans will still be there tomorrow.', lost: true
    })
  }

  showResult(data) {
    this.resultData = data
    const card = $('battle-result')
    card.classList.remove('hidden')
    const badgeHtml = data.badge ? `<div><span>SIGIL</span><b>${data.badge.sigil} ${data.badge.badge}</b></div>` : ''
    const levelHtml = data.levels?.length
      ? `<div><span>LEVEL</span><b>+${data.levels.length}</b></div>`
      : `<div><span>PARTY</span><b>${this.game.state.player.party.filter(c => c.hp > 0).length}/${this.game.state.player.party.length}</b></div>`
    const levelNotes = data.levels?.slice(0, 3).map(l => `${SPECIES[l.creature.speciesId].name} reached Lv ${l.to}${l.learned.length ? ' — learned ' + l.learned.join(', ') : ''}`).join('<br>') || ''
    card.innerHTML = `
      <div class="result-card">
        <div class="result-sigil">${data.win ? (data.badge ? data.badge.sigil : '✦') : '◌'}</div>
        <h2>${data.title}</h2>
        <div class="result-sub">${data.sub}</div>
        <div class="result-stats">
          <div><span>EXPERIENCE</span><b>+${data.xp}</b></div>
          ${levelHtml}
          ${badgeHtml}
        </div>
        <p class="result-copy">${data.copy}${levelNotes ? `<br><span style="color:#f2c96d">${levelNotes}</span>` : ''}</p>
        <div class="result-actions">
          <button class="btn btn-primary" id="result-continue"><span>${data.lost ? 'Return to the Waystone' : 'Return to the Wilds'}</span><i>→</i></button>
        </div>
      </div>`
    if (data.levels?.length) this.game.audio.levelUp()
    $('result-continue').addEventListener('click', () => {
      this.game.finishBattle(this)
    }, { once: true })
  }

  async tryCapture(wild) {
    if (this.isGym) { this.game.toast('Gym titans cannot be tamed.', '◈', 'bad'); return }
    const treat = TREATS[wild]
    if (!treat) return
    if ((this.game.state.player.treats[wild] || 0) <= 0) return
    this.game.state.player.treats[wild]--
    this.closePicker()
    this.phase = 'busy'
    this.busy = true
    this.updateUI()
    this.log(`You offer a <b>${treat.name}</b>…`)
    const sphere = new THREE.Mesh(new THREE.IcosahedronGeometry(0.26, 1), new THREE.MeshStandardMaterial({ color: TYPES[treat.type].color, emissive: TYPES[treat.type].color, emissiveIntensity: 1.6, roughness: 0.3 }))
    sphere.position.copy(this.pBase).add(new THREE.Vector3(0, 2.1, 0))
    this.arena.scene.add(sphere)
    const target = this.eBase.clone().add(new THREE.Vector3(0, 2.1, 0))
    await this.tween(650, (e) => {
      sphere.position.lerpVectors(this.pBase.clone().add(new THREE.Vector3(0, 2.1, 0)), target, e)
      sphere.position.y += Math.sin(e * Math.PI) * 2.6
      sphere.rotation.x += 0.2
      sphere.rotation.y += 0.25
    })
    this.arena.scene.remove(sphere)
    this.burst('enemy', TYPES[treat.type].color)
    $('flash').classList.add('on')
    setTimeout(() => $('flash').classList.remove('on'), 130)
    this.game.audio.capture()

    const chance = this.captureChance(wild)
    const success = Math.random() < chance
    if (success) {
      await delay(500)
      this.enemyModel.visible = false
      const level = this.enemy.level
      const caught = makeCreature(this.enemy.speciesId, level, { hp: Math.max(1, Math.round(this.enemy.maxHp * 0.55)) })
      const added = this.game.addCaptured(caught)
      const xp = Math.round(this.enemy.level * 7 + 10)
      for (const c of this.game.state.player.party) {
        if (c.hp > 0) this.grantXp(c, c === this.playerCreature ? xp : Math.round(xp * 0.4))
      }
      this.game.audio.levelUp()
      this.phase = 'done'
      this.showResult({
        win: true, title: 'Bond Formed', sub: added === 'party' ? 'A new companion joins your party' : 'Sent to the sanctuary',
        xp,
        copy: `${SPECIES[caught.speciesId].name} accepts your treat and presses its great head against your hand. You are bound now — by trust, not rope.${added === 'reserve' ? ' Your party was full, so it waits in the sanctuary.' : ''}`,
        caught: true
      })
      this.game.save()
      return
    }
    this.log(`<b>${this.enemyName()}</b> sniffs the treat, then refuses!`)
    this.floatText('RESISTED', 'enemy', '')
    await delay(450)
    await this.enemyTurn()
    if (this.phase === 'done') return
    await this.endRound()
  }

  captureChance(treatType) {
    const species = SPECIES[this.enemy.speciesId]
    const hpRatio = this.enemy.hp / this.enemy.maxHp
    const base = species.catchRate
    const hpFactor = 1 + (1 - hpRatio) * 2.3
    const leadLevel = this.playerCreature.level
    const levelFactor = clamp(1 - Math.max(0, this.enemy.level - leadLevel) * 0.018, 0.55, 1.15)
    const fav = treatType === species.type ? 1.45 : 0.82
    const status = this.enemy.statuses.length ? 1.12 : 1
    return clamp(base * hpFactor * levelFactor * fav * status, 0.04, 0.92)
  }

  openTreatPicker() {
    if (this.phase !== 'select' || this.isGym) {
      if (this.isGym) this.game.toast('Gym titans cannot be tamed.', '◈', 'bad')
      return
    }
    const picker = $('treat-picker')
    $('battle-command').classList.add('hidden')
    picker.classList.remove('hidden')
    const treats = Object.entries(this.game.state.player.treats).filter(([k, v]) => v > 0)
    const rows = treats.map(([type, count]) => {
      const t = TREATS[type]
      const chance = Math.round(this.captureChance(type) * 100)
      const fav = SPECIES[this.enemy.speciesId].favorite === type
      return `<button class="treat-card" data-treat="${type}" style="--tc:${TYPES[type].color}">
        <div class="tc-top"><b>${t.icon} ${t.name}</b><span class="tc-count">×${count}</span></div>
        <div class="tc-type">${TYPES[type].name}${fav ? ' · FAVORITE' : ''}</div>
        <div class="tc-rate">${chance}% bond chance${fav ? ' · +45%' : ''}</div>
      </button>`
    }).join('')
    picker.innerHTML = `<div class="treat-head"><h4>Offer a Treat</h4><button id="close-treat">×</button></div>
      <p style="margin:0 0 10px;font-size:0.6rem;color:#aab2c5;line-height:1.5">Weaken the titan first, and match its favorite flavor to improve the bond.</p>
      <div class="treat-grid">${rows || '<div class="empty-note">No treats yet. Gather ingredients and craft some at a waystone.</div>'}</div>`
    $('close-treat').onclick = () => { this.closePicker() }
    picker.querySelectorAll('[data-treat]').forEach(b => {
      b.addEventListener('click', () => this.tryCapture(b.dataset.treat))
    })
  }

  openSwapPicker() {
    if (this.phase !== 'select') return
    const picker = $('treat-picker')
    $('battle-command').classList.add('hidden')
    picker.classList.remove('hidden')
    const party = this.game.state.player.party
    const rows = party.map((c, i) => {
      const st = statsFor(SPECIES[c.speciesId], c.level)
      const type = TYPES[SPECIES[c.speciesId].type]
      const disabled = c.hp <= 0 || i === this.activeIdx
      return `<button class="treat-card" data-swap="${i}" style="--tc:${type.color};opacity:${disabled ? '.36' : '1'}" ${disabled ? 'disabled' : ''}>
        <div class="tc-top"><b>${type.icon} ${SPECIES[c.speciesId].name}</b><span class="tc-count">LV ${c.level}</span></div>
        <div class="tc-type">${type.name} · ${c.hp}/${st.hp} HP</div>
        <div class="tc-rate">${i === this.activeIdx ? 'IN BATTLE' : c.hp <= 0 ? 'FAINTED' : 'SWAP IN'}</div>
      </button>`
    }).join('')
    picker.innerHTML = `<div class="treat-head"><h4>Swap Companion</h4><button id="close-treat">×</button></div>
      <div class="treat-grid">${rows}</div>`
    $('close-treat').onclick = () => this.closePicker()
    picker.querySelectorAll('[data-swap]').forEach(b => {
      b.addEventListener('click', () => this.doSwap(Number(b.dataset.swap)))
    })
  }

  closePicker() {
    $('treat-picker').classList.add('hidden')
    $('treat-picker').innerHTML = ''
    $('battle-command').classList.remove('hidden')
    this.renderMoves()
  }

  async doSwap(index) {
    const c = this.game.state.player.party[index]
    if (!c || c.hp <= 0 || index === this.activeIdx) return
    this.closePicker()
    this.phase = 'busy'
    this.busy = true
    this.activeIdx = index
    this.playerCreature = c
    this.game.state.player.activeIndex = index
    this.playerStatuses = []
    this.focus = Math.min(this.maxFocus, this.focus + 2)
    this.buildModels()
    this.log(`Go, <b>${SPECIES[c.speciesId].name}</b>!`)
    this.updateUI()
    await delay(420)
    await this.enemyTurn()
    if (this.phase === 'done') return
    await this.endRound()
  }

  async brace() {
    if (this.phase !== 'select') return
    this.phase = 'busy'
    this.busy = true
    this.focus = Math.min(this.maxFocus, this.focus + 4)
    this.addStatus(this.playerStatuses, 'guard', 2)
    this.log(`${SPECIES[this.playerCreature.speciesId].name} braces, recovering focus and raising defense.`)
    this.game.audio.special()
    this.updateUI()
    await delay(360)
    await this.enemyTurn()
    if (this.phase === 'done') return
    await this.endRound()
  }

  async tryFlee() {
    if (this.phase !== 'select' || this.isGym) return
    if (Math.random() < 0.72) {
      this.phase = 'done'
      this.busy = true
      this.log('You slipped away into the undergrowth.')
      await delay(500)
      this.game.finishBattle(this, { fled: true })
      return
    }
    this.log('You could not escape!')
    this.game.audio.error()
    this.phase = 'busy'
    this.busy = true
    await delay(350)
    await this.enemyTurn()
    if (this.phase === 'done') return
    await this.endRound()
  }

  showHelp() {
    const tip = $('battle-tooltip')
    tip.classList.toggle('hidden')
    tip.innerHTML = '<b>Battle basics</b> — Every ability costs Focus. Focus restores +2 each turn; Brace restores +4 and raises defense. Match a titan’s favorite treat to improve capture. Swap to a fresh companion if you are in danger.'
    clearTimeout(this.helpTimer)
    this.helpTimer = setTimeout(() => tip.classList.add('hidden'), 6500)
  }

  update(dt, t) {
    if (this.destroyed) return
    this.arena.update(dt, t)
    this.playerModel?.userData.update?.(t, false)
    this.enemyModel?.userData.update?.(t + 1.3, false)
    if (this.shake > 0) {
      this.shake = Math.max(0, this.shake - dt * 1.8)
      const cam = this.arena.camera
      cam.position.x = (Math.random() - 0.5) * this.shake
      cam.position.y = 8.2 + (Math.random() - 0.5) * this.shake
      cam.lookAt(0, 3, 0)
    }
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const fx = this.effects[i]
      fx.life -= dt
      const pos = fx.pts.geometry.attributes.position
      for (let j = 0; j < fx.vel.length; j++) {
        fx.vel[j].y -= dt * 9
        pos.setXYZ(j, pos.getX(j) + fx.vel[j].x * dt, pos.getY(j) + fx.vel[j].y * dt, pos.getZ(j) + fx.vel[j].z * dt)
      }
      pos.needsUpdate = true
      fx.pts.material.opacity = clamp(fx.life / fx.max, 0, 1)
      if (fx.life <= 0) {
        this.arena.scene.remove(fx.pts)
        fx.pts.geometry.dispose()
        fx.pts.material.dispose()
        this.effects.splice(i, 1)
      }
    }
    if (this.playerModel) this.playerModel.rotation.y = this.playerModel.rotation.y * 0.985 + 0.01 * Math.atan2(this.eBase.x - this.pBase.x, this.eBase.z - this.pBase.z)
  }

  destroy() {
    this.destroyed = true
    this.abort.abort()
    clearTimeout(this.helpTimer)
    for (const fx of this.effects) {
      this.arena.scene.remove(fx.pts)
      fx.pts.geometry.dispose()
      fx.pts.material.dispose()
    }
    this.effects = []
    if (this.arena?.scene) {
      this.arena.scene.traverse(o => {
        if (o.geometry) o.geometry.dispose()
        if (o.material) {
          const mats = Array.isArray(o.material) ? o.material : [o.material]
          mats.forEach(m => { if (m.map) m.map.dispose(); m.dispose() })
        }
      })
    }
    $('battle-ui').querySelectorAll('.dmg-float').forEach(e => e.remove())
    $('battle-result').innerHTML = ''
    $('battle-result').classList.add('hidden')
    $('treat-picker').innerHTML = ''
    $('treat-picker').classList.add('hidden')
    $('battle-tooltip').classList.add('hidden')
    $('battle-command').classList.remove('hidden')
  }
}

import * as THREE from 'three'
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'
import './style.css'
import {
  SPECIES, REGIONS, TYPES, TREATS, INGREDIENTS, STARTERS, BADGES,
  SKIN_TONES, HAIR_COLORS, OUTFIT_COLORS, HAIR_STYLES,
  makeCreature, regionById, xpToNext, statsFor, movesFor, MOVES
} from './data.js'
import { buildRegion } from './world.js'
import { createTitleStage, createStageScene } from './stages.js'
import { buildTrainer } from './art.js'
import { Battle } from './battle.js'
import { AudioEngine } from './audio.js'

const $ = (id) => document.getElementById(id)
const clamp = (v, a, b) => Math.min(b, Math.max(a, v))
const SAVE_KEY = 'titanbound.save.v1'
const isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window

class Game {
  constructor() {
    this.state = null
    this.mode = 'loading'
    this.modalOpen = false
    this.dialogueOpen = false
    this.activeBattle = null
    this.world = null
    this.keys = new Set()
    this.touchMove = { x: 0, y: 0 }
    this.cameraYaw = 0
    this.cameraPitch = 0.17
    this.cameraZoom = 8.4
    this.playerPos = new THREE.Vector3()
    this.playerVY = 0
    this.jumping = false
    this.avatar = null
    this.avatarFacing = Math.PI
    this.nearest = null
    this.playTime = 0
    this.saveTimer = 0
    this.clock = new THREE.Clock()
    this.audio = new AudioEngine()
    this.isDragging = false
    this.dragLast = { x: 0, y: 0 }
    this.toastTimers = []
    this.boundFrame = this.frame.bind(this)
    this.creatorStep = 1
    this.starterIndex = 0
    this.journalTab = 'craft'
    this.creator = {
      gender: 'female', skin: SKIN_TONES[1], hairColor: HAIR_COLORS[1],
      outfit: OUTFIT_COLORS[0], hairStyle: 2, name: 'Aster'
    }
    this.initThree()
    this.bindUI()
    this.buildInterfaceOptions()
    this.loadSave()
    this.initStages()
    requestAnimationFrame(this.boundFrame)
    setTimeout(() => {
      $('load-fill').style.width = '100%'
      setTimeout(() => this.showTitle(), 450)
    }, 380)
  }

  initThree() {
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance', preserveDrawingBuffer: true })
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.35 : 1.75))
    renderer.setSize(window.innerWidth, window.innerHeight)
    renderer.shadowMap.enabled = true
    renderer.shadowMap.type = THREE.PCFSoftShadowMap
    renderer.toneMapping = THREE.ACESFilmicToneMapping
    renderer.toneMappingExposure = 1.12
    renderer.outputColorSpace = THREE.SRGBColorSpace
    renderer.domElement.setAttribute('aria-label', 'Titanbound 3D world')
    $('scene-host').appendChild(renderer.domElement)
    this.renderer = renderer

    this.camera = new THREE.PerspectiveCamera(52, window.innerWidth / window.innerHeight, 0.1, 340)
    this.worldCamera = new THREE.PerspectiveCamera(52, window.innerWidth / window.innerHeight, 0.1, 340)
    this.composer = new EffectComposer(renderer)
    this.renderPass = new RenderPass(new THREE.Scene(), this.camera)
    this.composer.addPass(this.renderPass)
    this.bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), isTouch ? 0.3 : 0.42, 0.6, 0.86)
    this.composer.addPass(this.bloomPass)
    this.composer.addPass(new OutputPass())
    this.activeCamera = this.camera
    this.scene = new THREE.Scene()

    window.addEventListener('resize', () => this.resize())
  }

  resize() {
    const w = window.innerWidth, h = window.innerHeight
    this.renderer.setSize(w, h)
    this.composer.setSize(w, h)
    for (const cam of [this.camera, this.worldCamera, this.titleStage?.camera, this.stage?.camera, this.activeBattle?.arena?.camera]) {
      if (cam && cam.isPerspectiveCamera) {
        cam.aspect = w / h
        cam.updateProjectionMatrix()
      }
    }
  }

  loadSave() {
    try {
      const raw = localStorage.getItem(SAVE_KEY)
      if (!raw) return
      const data = JSON.parse(raw)
      if (!data || data.v !== 1 || !data.player?.party?.length) return
      this.saved = data
    } catch (e) { console.warn('Save could not be read', e) }
  }

  save() {
    if (!this.state?.player) return
    const p = this.state.player
    if (this.mode === 'world') { p.x = this.playerPos.x; p.z = this.playerPos.z }
    const data = {
      v: 1, player: p, flags: this.state.flags || {}, playTime: Math.round(this.playTime),
      savedAt: Date.now()
    }
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(data))
      this.saved = data
      const el = $('save-state')
      el.textContent = 'SAVING…'
      el.classList.add('saving')
      clearTimeout(this.saveFlash)
      this.saveFlash = setTimeout(() => { el.textContent = 'AUTOSAVED'; el.classList.remove('saving') }, 700)
    } catch (e) { console.warn(e) }
  }

  initStages() {
    this.titleStage = createTitleStage()
    this.stage = createStageScene()
    this.setScene(this.titleStage.scene, this.titleStage.camera)
  }

  setScene(scene, camera) {
    this.scene = scene
    this.activeCamera = camera
    this.renderPass.scene = scene
    this.renderPass.camera = camera
  }

  showTitle() {
    this.mode = 'title'
    $('loading-screen').classList.add('out')
    $('creator-screen').classList.add('hidden')
    $('hud').classList.add('hidden')
    $('title-screen').classList.remove('hidden')
    $('btn-continue').classList.toggle('hidden', !this.saved)
    this.setScene(this.titleStage.scene, this.titleStage.camera)
    this.audio.setRegion('celestial')
  }

  startNew() {
    this.audio.init()
    this.audio.select()
    this.state = {
      player: null,
      flags: { tutorial: false, endingShown: false }
    }
    this.creatorStep = 1
    this.starterIndex = 0
    this.creator = {
      gender: 'female', skin: SKIN_TONES[1], hairColor: HAIR_COLORS[1],
      outfit: OUTFIT_COLORS[0], hairStyle: 2, name: 'Aster'
    }
    $('trainer-name').value = 'Aster'
    this.mode = 'creator'
    $('title-screen').classList.add('hidden')
    $('creator-screen').classList.remove('hidden')
    $('creator-step-1').classList.remove('hidden')
    $('creator-step-2').classList.add('hidden')
    this.updateStepDots(1)
    this.stage.setTrainer(this.creator)
    this.stage.setMode('trainer')
    this.setScene(this.stage.scene, this.stage.camera)
    this.syncCreatorUI()
    this.renderStarterCards()
  }

  continueGame() {
    if (!this.saved) return
    this.audio.init()
    const p = this.saved.player
    this.state = { player: p, flags: this.saved.flags || {} }
    this.playTime = this.saved.playTime || 0
    $('title-screen').classList.add('hidden')
    $('creator-screen').classList.add('hidden')
    this.enterRegion(p.regionId || 'verdant', { x: p.x, z: p.z, silent: true })
    this.audio.select()
    this.toast(`Welcome back, ${p.name}.`, '✦')
  }

  buildInterfaceOptions() {
    const skin = $('skin-select')
    skin.innerHTML = SKIN_TONES.map(c => `<button class="swatch" data-skin="${c}" style="background:${c}" title="Skin tone"></button>`).join('')
    const hair = $('hair-color-select')
    hair.innerHTML = HAIR_COLORS.map(c => `<button class="swatch" data-hair="${c}" style="background:${c}" title="Hair color"></button>`).join('')
    const outfit = $('outfit-select')
    outfit.innerHTML = OUTFIT_COLORS.map(c => `<button class="swatch" data-outfit="${c}" style="background:${c}" title="Outfit color"></button>`).join('')
    const styles = $('hair-style-select')
    styles.innerHTML = HAIR_STYLES.map((s, i) => `<button class="hair-opt" data-style="${i}">${s.slice(0, 4)}</button>`).join('')

    $('gender-select').addEventListener('click', (e) => {
      const b = e.target.closest('[data-value]')
      if (!b) return
      this.creator.gender = b.dataset.value
      this.audio.click()
      this.syncCreatorUI()
    })
    skin.addEventListener('click', (e) => {
      const b = e.target.closest('[data-skin]')
      if (!b) return
      this.creator.skin = b.dataset.skin
      this.audio.click(); this.syncCreatorUI()
    })
    hair.addEventListener('click', (e) => {
      const b = e.target.closest('[data-hair]')
      if (!b) return
      this.creator.hairColor = b.dataset.hair
      this.audio.click(); this.syncCreatorUI()
    })
    outfit.addEventListener('click', (e) => {
      const b = e.target.closest('[data-outfit]')
      if (!b) return
      this.creator.outfit = b.dataset.outfit
      this.audio.click(); this.syncCreatorUI()
    })
    styles.addEventListener('click', (e) => {
      const b = e.target.closest('[data-style]')
      if (!b) return
      this.creator.hairStyle = Number(b.dataset.style)
      this.audio.click(); this.syncCreatorUI()
    })
    $('trainer-name').addEventListener('input', (e) => { this.creator.name = e.target.value.slice(0, 16) })
    $('btn-randomize').addEventListener('click', () => {
      const pick = (arr) => arr[Math.floor(Math.random() * arr.length)]
      this.creator.skin = pick(SKIN_TONES)
      this.creator.hairColor = pick(HAIR_COLORS)
      this.creator.outfit = pick(OUTFIT_COLORS)
      this.creator.hairStyle = Math.floor(Math.random() * HAIR_STYLES.length)
      this.creator.gender = Math.random() > 0.5 ? 'female' : 'male'
      this.audio.select(); this.syncCreatorUI()
    })
    $('btn-to-partner').addEventListener('click', () => {
      const name = $('trainer-name').value.trim()
      if (!name) { $('trainer-name').focus(); this.toast('Every keeper needs a name.', '!', 'bad'); this.audio.error(); return }
      this.creator.name = name
      this.audio.select()
      this.showStarterStep()
    })
    $('btn-back-to-look').addEventListener('click', () => {
      this.creatorStep = 1
      $('creator-step-2').classList.add('hidden')
      $('creator-step-1').classList.remove('hidden')
      this.updateStepDots(1)
      this.stage.setMode('trainer')
      this.audio.click()
    })
    $('btn-begin').addEventListener('click', () => this.beginJourney())
    $('creator-back').addEventListener('click', () => {
      if (this.creatorStep === 2) { $('btn-back-to-look').click(); return }
      this.showTitle(); this.audio.click()
    })
  }

  syncCreatorUI() {
    const c = this.creator
    document.querySelectorAll('#gender-select button').forEach(b => b.classList.toggle('active', b.dataset.value === c.gender))
    document.querySelectorAll('#skin-select .swatch').forEach(b => b.classList.toggle('active', b.dataset.skin === c.skin))
    document.querySelectorAll('#hair-color-select .swatch').forEach(b => b.classList.toggle('active', b.dataset.hair === c.hairColor))
    document.querySelectorAll('#outfit-select .swatch').forEach(b => b.classList.toggle('active', b.dataset.outfit === c.outfit))
    document.querySelectorAll('#hair-style-select .hair-opt').forEach(b => b.classList.toggle('active', Number(b.dataset.style) === c.hairStyle))
    this.stage.setTrainer(c)
  }

  updateStepDots(step) {
    document.querySelectorAll('.step-dot').forEach(d => d.classList.toggle('active', Number(d.dataset.step) === step))
  }

  showStarterStep() {
    this.creatorStep = 2
    $('creator-step-1').classList.add('hidden')
    $('creator-step-2').classList.remove('hidden')
    this.updateStepDots(2)
    this.stage.setMode('starters')
    this.stage.selectStarter(this.starterIndex)
    this.setScene(this.stage.scene, this.stage.camera)
    this.renderStarterCards()
  }

  renderStarterCards() {
    const wrap = $('starter-cards')
    wrap.innerHTML = STARTERS.map((id, i) => {
      const s = SPECIES[id]
      const t = TYPES[s.type]
      return `<button class="starter-card ${i === this.starterIndex ? 'active' : ''}" data-starter="${i}" style="--sc:${t.color}">
        <span class="card-num">0${i + 1}</span>
        <span class="type-chip">${t.icon} ${t.name}</span>
        <h3>${s.name}</h3>
        <span class="epithet">${s.epithet}</span>
        <p>${s.desc}</p>
        <div class="pick-line"><span>${i === this.starterIndex ? 'CHOSEN PARTNER' : 'CHOOSE THIS TITAN'}</span><span>${i === this.starterIndex ? '✦' : '→'}</span></div>
      </button>`
    }).join('')
    wrap.querySelectorAll('[data-starter]').forEach(b => {
      b.addEventListener('click', () => {
        this.starterIndex = Number(b.dataset.starter)
        this.stage.selectStarter(this.starterIndex)
        this.renderStarterCards()
        this.audio.select()
      })
    })
  }

  beginJourney() {
    const id = STARTERS[this.starterIndex]
    const species = SPECIES[id]
    const starter = makeCreature(id, 5)
    const p = {
      name: this.creator.name || 'Aster',
      gender: this.creator.gender, skin: this.creator.skin, hairColor: this.creator.hairColor,
      outfit: this.creator.outfit, hairStyle: this.creator.hairStyle,
      regionId: 'verdant', x: 0, z: 18.4,
      badges: [], party: [starter], reserve: [], activeIndex: 0,
      inventory: { sunpetal: 2, wildgrain: 3 },
      treats: { [species.type]: 1 },
      discovered: [id], seen: [id],
      startedAt: Date.now()
    }
    this.state.player = p
    this.playTime = 0
    this.audio.init()
    this.audio.badge()
    $('creator-screen').classList.add('hidden')
    this.enterRegion('verdant', { silent: true })
    this.save()
    setTimeout(() => {
      this.toast('WASD or the left stick to move · drag to look', '◈')
    }, 600)
    setTimeout(() => {
      this.toast('Gather glowing plants, then craft treats in your Journal [C]', '✦')
    }, 3200)
    setTimeout(() => this.showIntroDialogue(), 1100)
  }

  showIntroDialogue() {
    this.showDialogue({
      portrait: 'W', name: 'Wren Thistle', title: 'Rootbound Warden',
      text: `So the isles have sent me a new keeper. Good. The titans are restless, and the eight sigils have gone quiet. Start at my grove beyond the path — but first, gather sunpetal. A titan trusts a full hand more than a fast one.`,
      actions: [{ label: 'I understand', onClick: () => this.toast('Objective: reach the Amberstep Grove', '◇') }]
    })
  }

  bindUI() {
    $('btn-new').addEventListener('click', () => this.startNew())
    $('btn-continue').addEventListener('click', () => this.continueGame())
    $('btn-atlas').addEventListener('click', () => this.openAtlas())
    $('btn-journal').addEventListener('click', () => this.openJournal(this.journalTab))
    $('btn-sound').addEventListener('click', () => this.toggleSound())
    $('party-dock').addEventListener('click', () => this.openJournal('party'))
    $('dialogue-close').addEventListener('click', () => this.closeDialogue())
    $('mobile-interact').addEventListener('click', () => this.interact())
    $('mobile-journal').addEventListener('click', () => this.openJournal(this.journalTab))
    $('btn-atlas').addEventListener('mouseenter', () => this.audio.click())
    $('btn-journal').addEventListener('mouseenter', () => this.audio.click())
    $('battle-sound')?.addEventListener('click', () => this.toggleSound())
    $('modal-layer').addEventListener('click', (e) => {
      if (e.target === $('modal-layer')) this.closeModal()
    })
    window.addEventListener('keydown', (e) => this.onKeyDown(e))
    window.addEventListener('keyup', (e) => this.keys.delete(e.code))
    this.bindPointer()
    this.bindJoystick()
  }

  toggleSound() {
    if (!this.audio.ctx) this.audio.init()
    const on = this.audio.toggle()
    this.toast(on ? 'Sound on' : 'Sound muted', on ? '♪' : '◌')
  }

  bindPointer() {
    const canvas = this.renderer.domElement
    canvas.addEventListener('pointerdown', (e) => {
      if (this.mode !== 'world' || this.modalOpen || this.dialogueOpen) return
      this.isDragging = true
      this.dragLast.x = e.clientX; this.dragLast.y = e.clientY
      canvas.setPointerCapture?.(e.pointerId)
    })
    canvas.addEventListener('pointermove', (e) => {
      if (!this.isDragging) return
      const dx = e.clientX - this.dragLast.x
      const dy = e.clientY - this.dragLast.y
      this.dragLast.x = e.clientX; this.dragLast.y = e.clientY
      this.cameraYaw -= dx * 0.006
      this.cameraPitch = clamp(this.cameraPitch + dy * 0.0035, -0.08, 0.62)
    })
    const stop = () => { this.isDragging = false }
    canvas.addEventListener('pointerup', stop)
    canvas.addEventListener('pointercancel', stop)
    canvas.addEventListener('wheel', (e) => {
      if (this.mode !== 'world' || this.modalOpen) return
      e.preventDefault()
      this.cameraZoom = clamp(this cameraZoom => 0, 0, 0)
    }, { passive: false })
    canvas.addEventListener('wheel', (e) => {
      if (this.mode !== 'world' || this.modalOpen) return
      e.preventDefault()
      this.cameraZoom = clamp(this.cameraZoom + e.deltaY * 0.006, 5.8, 12.5)
    }, { passive: false })
  }

  bindJoystick() {
    const base = $('joystick')
    const knob = $('joystick-knob')
    let id = null
    let cx = 0, cy = 0
    const radius = 37
    const move = (e) => {
      if (id !== e.pointerId) return
      let dx = e.clientX - cx, dy = e.clientY - cy
      const d = Math.hypot(dx, dy)
      if (d > radius) { dx = dx / d * radius; dy = dy / d * radius }
      knob.style.transform = `translate(${dx}px, ${dy}px)`
      this.touchMove.x = dx / radius
      this.touchMove.y = -dy / radius
    }
    base.addEventListener('pointerdown', (e) => {
      id = e.pointerId
      const r = base.getBoundingClientRect()
      cx = r.left + r.width / 2
      cy = r.top + r.height / 2
      base.setPointerCapture?.(e.pointerId)
      move(e)
    })
    base.addEventListener('pointermove', move)
    const stop = (e) => {
      if (id !== e.pointerId) return
      id = null
      knob.style.transform = 'translate(0,0)'
      this.touchMove.x = 0; this.touchMove.y = 0
    }
    base.addEventListener('pointerup', stop)
    base.addEventListener('pointercancel', stop)
  }

  onKeyDown(e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return
    if (e.code === 'Escape') {
      if (this.dialogueOpen) this.closeDialogue()
      else if (this.modalOpen) this.closeModal()
      return
    }
    if (this.mode === 'world' && !this.modalOpen && !this.dialogueOpen && !e.repeat) {
      if (e.code === 'KeyE') { e.preventDefault(); this.interact() }
      if (e.code === 'KeyM') { e.preventDefault(); this.openAtlas() }
      if (e.code === 'KeyC') { e.preventDefault(); this.openJournal(this.journalTab) }
      if (e.code === 'Space') { e.preventDefault(); this.jump() }
    }
    if (this.mode === 'battle' && this.activeBattle && !this.activeBattle.busy) {
      if (['Digit1', 'Digit2', 'Digit3', 'Digit4'].includes(e.code)) {
        const idx = Number(e.code.slice(-1)) - 1
        const moves = movesFor(SPECIES[this.activeBattle.playerCreature.speciesId], this.activeBattle.playerCreature.level)
        if (moves[idx]) this.activeBattle.useMove(moves[idx])
      }
    }
    if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(e.code)) {
      this.keys.add(e.code)
    }
  }

  jump() {
    if (!this.jumping && this.mode === 'world') {
      this.jumping = true
      this.playerVY = 5.6
      this.audio.whoosh()
    }
  }

  interact() {
    if (this.mode !== 'world' || this.modalOpen || this.dialogueOpen) return
    if (!this.nearest) { this.audio.error(); return }
    this.audio.click()
    const n = this.nearest
    if (n.type === 'wild') this.startWildBattle(n.target)
    else if (n.type === 'resource') this.collectResource(n.target)
    else if (n.type === 'waystone') this.openAtlas()
    else if (n.type === 'gym') this.talkToGym()
  }

  enterRegion(id, opts = {}) {
    const region = regionById(id)
    if (this.world) {
      this.world.dispose()
      this.world = null
    }
    if (this.avatar) {
      this.avatar.parent?.remove(this.avatar)
      this.avatar = null
    }
    this.world = buildRegion(id)
    this.state.player.regionId = id
    this.world.scene.add(this.world.particles?.points || new THREE.Group())
    this.playerPos.set(opts.x ?? this.world.spawn.x, 0, opts.z ?? this.world.spawn.z)
    if (opts.x === undefined) { this.playerPos.x = this.world.spawn.x; this.playerPos.z = this.world.spawn.z }
    this.playerPos.y = this.world.heightAt(this.playerPos.x, this.playerPos.z)
    this.cameraYaw = 0
    this.cameraPitch = 0.17
    this.cameraZoom = 8.4
    this.createAvatar()
    this.avatar.position.copy(this.playerPos)
    this.avatar.rotation.y = Math.PI
    this.avatarFacing = Math.PI
    this.setScene(this.world.scene, this.worldCamera)
    this.mode = 'world'
    this.modalOpen = false
    this.dialogueOpen = false
    this.playerVY = 0
    this.jumping = false
    this.nearest = null
    $('hud').classList.remove('hidden')
    $('battle-ui').classList.add('hidden')
    $('dialogue').classList.add('hidden')
    this.closeModal()
    for (const sp of region.creatures) {
      if (!this.state.player.seen.includes(sp)) this.state.player.seen.push(sp)
    }
    this.state.player.activeIndex = clamp(this.state.player.activeIndex || 0, 0, this.state.player.party.length - 1)
    this.audio.setRegion(id)
    this.refreshHUD()
    this.updateCamera(0, true)
    if (!opts.silent) {
      this.toast(`${region.name} — ${region.subtitle}`, '◇')
      this.save()
    }
    $('load-fill').style.width = '100%'
    $('loading-screen').classList.add('out')
  }

  createAvatar() {
    const p = this.state.player
    this.avatar = buildTrainer({ gender: p.gender, skin: p.skin, hairColor: p.hairColor, outfit: p.outfit, hairStyle: p.hairStyle })
    this.avatar.traverse(o => { if (o.isMesh) { o.castShadow = true } })
    this.world.scene.add(this.avatar)
  }

  frame(now) {
    const dt = Math.min(this.clock.getDelta(), 0.05)
    const t = performance.now() / 1000
    if (this.mode === 'title') this.titleStage.update(dt, t)
    else if (this.mode === 'creator') this.stage.update(dt, t)
    else if (this.mode === 'world') {
      this.updateWorld(dt, t)
      if (!this.modalOpen && !this.dialogueOpen) this.playTime += dt
    } else if (this.mode === 'battle' && this.activeBattle) this.activeBattle.update(dt, t)
    this.composer.render()
    requestAnimationFrame(this.boundFrame)
  }

  updateWorld(dt, t) {
    if (!this.world) return
    this.world.update(dt, t)
    if (this.mode === 'world' && !this.modalOpen && !this.dialogueOpen) this.updatePlayer(dt)
    this.updateCamera(dt)
    this.updateInteraction()
    this.updateMinimap()
    if (this.mode === 'world') {
      this.saveTimer += dt
      if (this.saveTimer > 20) { this.saveTimer = 0; this.save() }
    }
  }

  updatePlayer(dt) {
    let mx = 0, mz = 0
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) mz += 1
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) mz -= 1
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) mx += 1
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) mx -= 1
    mx += this.touchMove.x
    mz += this.touchMove.y
    const len = Math.hypot(mx, mz)
    if (len > 1) { mx /= len; mz /= len }
    const forwardX = -Math.sin(this.cameraYaw)
    const forwardZ = -Math.cos(this.cameraYaw)
    const rightX = Math.cos(this.cameraYaw)
    const rightZ = -Math.sin(this.cameraYaw)
    let dx = forwardX * mz + rightX * mx
    let dz = forwardZ * mz + rightZ * mx
    const moving = Math.hypot(dx, dz) > 0.05
    const sprint = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight')
    const speed = moving ? (sprint ? 10.2 : 6.9) : 0
    if (moving) {
      const dl = Math.hypot(dx, dz)
      dx /= dl; dz /= dl
      this.playerPos.x += dx * speed * dt
      this.playerPos.z += dz * speed * dt
      const r = Math.hypot(this.playerPos.x, this.playerPos.z)
      if (r > 55) {
        this.playerPos.x = this.playerPos.x / r * 55
        this.playerPos.z = this.playerPos.z / r * 55
      }
      const targetAngle = Math.atan2(dx, dz)
      let diff = targetAngle - this.avatarFacing
      while (diff > Math.PI) diff -= Math.PI * 2
      while (diff < -Math.PI) diff += Math.PI * 2
      this.avatarFacing += diff * Math.min(1, dt * 12)
    }
    const ground = this.world.heightAt(this.playerPos.x, this.playerPos.z)
    if (this.jumping) {
      this.playerVY -= 16 * dt
      this.playerPos.y += this.playerVY * dt
      if (this.playerPos.y <= ground) {
        this.playerPos.y = ground
        this.playerVY = 0
        this.jumping = false
      }
    } else {
      this.playerPos.y += (ground - this.playerPos.y) * Math.min(1, dt * 14)
    }
    if (this.avatar) {
      this.avatar.position.copy(this.playerPos)
      this.avatar.rotation.y = this.avatarFacing
      this.avatar.userData.update?.(t, moving)
    }
    if (moving) {
      const p = this.world.particles
      if (Math.random() < dt * 10) {
        // subtle dust at the keeper's feet
      }
    }
  }

  updateCamera(dt, instant = false) {
    if (!this.avatar) return
    const dist = this.cameraZoom
    const cosP = Math.cos(this.cameraPitch)
    const targetX = this.playerPos.x + Math.sin(this.cameraYaw) * dist * cosP
    const targetZ = this.playerPos.z + Math.cos(this.cameraYaw) * dist * cosP
    let targetY = this.playerPos.y + 2.2 + Math.sin(this.cameraPitch) * dist * 0.72
    const groundAtCam = this.world.heightAt(targetX, targetZ)
    targetY = Math.max(targetY, groundAtCam + 1.3)
    const lookX = this.playerPos.x
    const lookY = this.playerPos.y + 2.2
    const lookZ = this.playerPos.z
    if (instant) {
      this.worldCamera.position.set(targetX, targetY, targetZ)
    } else {
      const lerp = 1 - Math.exp(-dt * 7.5)
      this.worldCamera.position.lerp(new THREE.Vector3(targetX, targetY, targetZ), lerp)
    }
    this.worldCamera.lookAt(lookX, lookY, lookZ)
  }

  updateInteraction() {
    if (!this.world || this.modalOpen || this.dialogueOpen || this.mode !== 'world') {
      $('interact-prompt').classList.add('hidden')
      this.nearest = null
      return
    }
    let best = null
    let bestDist = Infinity
    const consider = (type, target, dist, label, sub) => {
      if (dist < bestDist) { bestDist = dist; best = { type, target, label, sub, dist } }
    }
    for (const w of this.world.wilds) {
      if (!w.active) continue
      const d = Math.hypot(w.x - this.playerPos.x, w.z - this.playerPos.z)
      if (d < 8.4) consider('wild', w, d, `Challenge ${SPECIES[w.speciesId].name}`, `${TYPES[SPECIES[w.speciesId].type].name} · Lv ${w.level} · Wild Titan`)
    }
    for (const r of this.world.resources) {
      if (!r.active) continue
      const d = Math.hypot(r.group.position.x - this.playerPos.x, r.group.position.z - this.playerPos.z)
      if (d < 4.6) consider('resource', r, d, `Gather ${INGREDIENTS[this.world.region.material].name}`, `Scavenge · +2 ${INGREDIENTS[this.world.region.material].name}, +1 Wildgrain`)
    }
    const wd = Math.hypot(this.world.waystone.pos.x - this.playerPos.x, this.world.waystone.pos.z - this.playerPos.z)
    if (wd < 6.2) consider('waystone', this.world.waystone, wd, 'Open the Atlas', 'Waystone · Travel & rest')
    const gd = Math.hypot(this.world.gym.interactPos.x - this.playerPos.x, this.world.gym.interactPos.z - this.playerPos.z)
    if (gd < 11.5) {
      const cleared = this.state.player.badges.includes(this.world.region.id)
      consider('gym', this.world.gym, gd, `Challenge ${this.world.region.gym.leader}`, cleared ? `${this.world.region.gym.name} · Sigil earned` : `${this.world.region.gym.name} · ${TYPES[this.world.region.type].name} Gym`)
    }
    this.nearest = best
    const prompt = $('interact-prompt')
    if (best) {
      prompt.classList.remove('hidden')
      $('interact-label').textContent = best.label
      $('interact-sub').textContent = best.sub
    } else {
      prompt.classList.add('hidden')
    }
  }

  collectResource(res) {
    if (!res.active) return
    res.active = false
    res.group.visible = false
    res.respawnAt = performance.now() + 50000
    const mat = this.world.region.material
    this.state.player.inventory[mat] = (this.state.player.inventory[mat] || 0) + 2
    this.state.player.inventory.wildgrain = (this.state.player.inventory.wildgrain || 0) + 1
    this.audio.select()
    $('flash').classList.add('on')
    setTimeout(() => $('flash').classList.remove('on'), 80)
    this.toast(`+2 ${INGREDIENTS[mat].name} · +1 Wildgrain`, INGREDIENTS[mat].icon, 'good')
    this.save()
  }

  startWildBattle(wild) {
    if (!wild.active) return
    if (!this.state.player.party.some(c => c.hp > 0)) {
      this.toast('Your party is exhausted. Rest at a waystone.', '◌', 'bad')
      return
    }
    this.startBattle({ type: 'wild', wild, regionId: this.state.player.regionId })
  }

  talkToGym() {
    const region = this.world.region
    const gym = region.gym
    const cleared = this.state.player.badges.includes(region.id)
    if (cleared) {
      this.showDialogue({
        portrait: gym.leader[0], name: gym.leader, title: gym.title,
        text: `The sigil is yours, and the grove remembers. ${gym.quote} If you seek the rest of the circle, the waystone will carry you.`,
        actions: [{ label: 'Farewell', onClick: () => {} }]
      })
      return
    }
    this.showDialogue({
      portrait: gym.leader[0], name: gym.leader, title: gym.title,
      text: `I am ${gym.leader}, keeper of ${gym.name}. ${gym.quote} My titans have held this ground for a long time. Show me a bond that can move them.`,
      actions: [
        { label: `Challenge · Lv ${Math.min(...gym.team.map(m => m.level))}–${Math.max(...gym.team.map(m => m.level))}`, onClick: () => this.startBattle({ type: 'gym', gym, regionId: region.id }) },
        { label: 'Not yet', onClick: () => {} }
      ]
    })
  }

  startBattle(config) {
    this.closeDialogue()
    this.closeModal()
    if (this.modalOpen) return
    this.audio.init()
    this.audio.whoosh()
    $('flash').classList.add('on')
    setTimeout(() => $('flash').classList.remove('on'), 120)
    this.mode = 'battle'
    this.activeBattle = new Battle(this, config)
    this.setScene(this.activeBattle.arena.scene, this.activeBattle.arena.camera)
    this.resize()
  }

  enterBattleMode(battle) {
    this.mode = 'battle'
    $('hud').classList.add('hidden')
    $('interact-prompt').classList.add('hidden')
  }

  showBattleUI(show) {
    $('battle-ui').classList.toggle('hidden', !show)
  }

  finishBattle(battle, opts = {}) {
    const data = battle.resultData || {}
    battle.destroy()
    this.activeBattle = null
    this.mode = 'world'
    this.showBattleUI(false)
    this.setScene(this.world.scene, this.worldCamera)
    if (data.lost) {
      const ws = this.world.waystone.pos
      this.playerPos.set(ws.x, this.world.heightAt(ws.x, ws.z + 3.2), ws.z + 3.2)
      for (const c of this.state.player.party) {
        const st = statsFor(SPECIES[c.speciesId], c.level)
        c.hp = st.hp
        c.maxHp = st.hp
      }
      this.toast('Your party was tended at the waystone.', '✦', 'good')
    }
    if (data.badge) {
      this.toast(`Sigil earned: ${data.badge.badge}`, data.badge.sigil, 'good')
      setTimeout(() => this.checkEnding(), 750)
    }
    if (data.caught) {
      // result copy already explained the bond
    }
    if (opts.fled) this.toast('You escaped the encounter.', '↩')
    $('hud').classList.remove('hidden')
    this.refreshHUD()
    this.updateCamera(0, true)
    this.save()
    this.audio.setRegion(this.state.player.regionId)
  }

  checkEnding() {
    if (this.state.player.badges.length >= 8 && !this.state.flags.endingShown) {
      this.state.flags.endingShown = true
      this.save()
      this.audio.badge()
      this.openModal(`<div class="modal-shell" style="max-width:720px">
        <div class="modal-head">
          <div><div class="panel-eyebrow">THE EIGHTFOLD CIRCLE</div><h2>A Keeper of the Isles</h2><p>Eight sigils. Eight keepers. One bond.</p></div>
          <button class="modal-close" data-close>×</button>
        </div>
        <div class="modal-body" style="text-align:center;padding-bottom:40px">
          <div style="font-size:3rem;color:#f2c96d;text-shadow:0 0 40px rgba(242,201,109,.5)">✦</div>
          <p style="max-width:500px;margin:20px auto;font-size:0.82rem;line-height:1.85;color:#cfd3dd;font-weight:300">
            The last sigil settles into your keeper's ring. Somewhere beyond the fog, the titans answer with a sound like mountains remembering their names.
            <br><br>
            You came to the isles with one small friend and a handful of treats. You leave with a circle of eight, and the wilds themselves know your footsteps.
          </p>
          <button class="btn btn-primary" data-close style="margin:0 auto"><span>Keep Exploring</span><i>✦</i></button>
        </div>
      </div>`)
    }
  }

  addCaptured(creature) {
    const p = this.state.player
    if (!p.discovered.includes(creature.speciesId)) p.discovered.push(creature.speciesId)
    if (!p.seen.includes(creature.speciesId)) p.seen.push(creature.speciesId)
    if (p.party.length < 6) {
      p.party.push(creature)
      return 'party'
    }
    p.reserve.push(creature)
    return 'reserve'
  }

  refreshHUD() {
    if (!this.state?.player) return
    const p = this.state.player
    const region = regionById(p.regionId)
    const type = TYPES[region.type]
    $('hud-region-index').textContent = String(region.number).padStart(2, '0')
    $('hud-region-name').textContent = region.name
    $('hud-region-sub').textContent = region.subtitle
    $('hud-region-type').textContent = type.name
    $('hud-region-type').style.setProperty('--type', type.color)
    $('hud-region').style.borderLeftColor = type.color
    $('map-caption').textContent = region.name.toUpperCase()
    $('keeper-name').textContent = p.name
    $('keeper-initial').textContent = p.name[0]?.toUpperCase() || 'A'
    const rank = p.badges.length >= 8 ? 'Isle Champion' : p.badges.length >= 6 ? 'High Keeper' : p.badges.length >= 3 ? 'Sigil Seeker' : p.badges.length >= 1 ? 'Trail Keeper' : 'Novice Keeper'
    $('keeper-title').textContent = rank
    $('badge-rack').innerHTML = BADGES.map(b => {
      const earned = p.badges.includes(b.id)
      return `<div class="badge-slot ${earned ? 'earned' : ''}" style="--bc:${TYPES[b.type].color}" title="${b.name} — ${b.leader}">${b.sigil}</div>`
    }).join('')
    const cleared = p.badges.includes(region.id)
    if (!cleared) {
      $('hud-objective-text').textContent = `${region.gym.leader} waits at ${region.gym.name}`
    } else if (p.badges.length >= 8) {
      $('hud-objective-text').textContent = 'The Eightfold Circle is complete'
    } else {
      $('hud-objective-text').textContent = 'Travel onward — another sigil awaits'
    }
    const party = p.party
    $('party-dock').innerHTML = party.map((c, i) => {
      const sp = SPECIES[c.speciesId]
      const tt = TYPES[sp.type]
      const st = statsFor(sp, c.level)
      return `<div class="party-pill ${i === p.activeIndex ? 'active' : ''} ${c.hp <= 0 ? 'fainted' : ''}" style="--bc:${tt.color}" data-party="${i}">
        <div class="orb">${tt.icon}</div>
        <div><b>${sp.name}</b><span>Lv ${c.level}</span></div>
        <div class="mini-hp"><i style="width:${clamp(c.hp / st.hp * 100, 0, 100)}%;background:${c.hp / st.hp < 0.3 ? '#ff766b' : '#78e4a2'}"></i></div>
      </div>`
    }).join('')
    $('party-dock').querySelectorAll('[data-party]').forEach(el => {
      el.addEventListener('click', () => {
        p.activeIndex = Number(el.dataset.party)
        this.audio.click()
        this.refreshHUD()
        this.save()
      })
    })
  }

  updateMinimap() {
    if (!this.world) return
    const canvas = $('minimap')
    const ctx = canvas.getContext('2d')
    const w = canvas.width, h = canvas.height
    const cx = w / 2, cy = h / 2
    const scale = 2.36
    ctx.clearRect(0, 0, w, h)
    const region = this.world.region
    const pal = region.palette
    const grad = ctx.createRadialGradient(cx, cy, 20, cx, cy, 154)
    grad.addColorStop(0, 'rgba(34,49,63,0.55)')
    grad.addColorStop(1, 'rgba(6,10,18,0.25)')
    ctx.fillStyle = grad
    ctx.beginPath(); ctx.arc(cx, cy, 154, 0, Math.PI * 2); ctx.fill()
    ctx.strokeStyle = 'rgba(255,255,255,0.08)'
    ctx.lineWidth = 1
    for (const rr of [52, 100, 145]) {
      ctx.beginPath(); ctx.arc(cx, cy, rr, 0, Math.PI * 2); ctx.stroke()
    }
    ctx.beginPath(); ctx.moveTo(cx - 150, cy); ctx.lineTo(cx + 150, cy); ctx.moveTo(cx, cy - 150); ctx.lineTo(cx, cy + 150); ctx.stroke()
    const toMap = (x, z) => [cx + x * scale, cy + z * scale]
    const clampPoint = (x, z) => {
      const dx = x - this.playerPos.x, dz = z - this.playerPos.z
      return [cx + dx * scale, cy + dz * scale]
    }
    for (const r of this.world.resources) {
      if (!r.active) continue
      const [x, y] = clampPoint(r.group.position.x, r.group.position.z)
      if (Math.hypot(x - cx, y - cy) > 150) continue
      ctx.fillStyle = pal.glow
      ctx.beginPath(); ctx.arc(x, y, 2.4, 0, Math.PI * 2); ctx.fill()
    }
    for (const wd of this.world.wilds) {
      if (!wd.active) continue
      const [x, y] = clampPoint(wd.x, wd.z)
      if (Math.hypot(x - cx, y - cy) > 150) continue
      ctx.fillStyle = TYPES[SPECIES[wd.speciesId].type].color
      ctx.beginPath(); ctx.arc(x, y, 3.5, 0, Math.PI * 2); ctx.fill()
      ctx.strokeStyle = 'rgba(0,0,0,0.45)'; ctx.stroke()
    }
    const [gx, gy] = clampPoint(this.world.gym.pos.x, this.world.gym.pos.z)
    if (Math.hypot(gx - cx, gy - cy) < 150) {
      ctx.save(); ctx.translate(gx, gy); ctx.rotate(Math.PI / 4)
      ctx.fillStyle = this.state.player.badges.includes(region.id) ? pal.glow : '#f2c96d'
      ctx.fillRect(-6, -6, 12, 12)
      ctx.strokeStyle = '#0a0f1b'; ctx.lineWidth = 2; ctx.strokeRect(-6, -6, 12, 12)
      ctx.restore()
    }
    const [wx, wy] = clampPoint(this.world.waystone.pos.x, this.world.waystone.pos.z)
    if (Math.hypot(wx - cx, wy - cy) < 150) {
      ctx.fillStyle = '#8fe8ff'; ctx.fillRect(wx - 4, wy - 4, 8, 8)
      ctx.strokeStyle = 'rgba(10,20,30,0.7)'; ctx.strokeRect(wx - 4, wy - 4, 8, 8)
    }
    ctx.save(); ctx.translate(cx, cy); ctx.rotate(-this.avatarFacing)
    ctx.fillStyle = '#fff4ce'
    ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(5.5, 7); ctx.lineTo(0, 4); ctx.lineTo(-5.5, 7); ctx.closePath(); ctx.fill()
    ctx.restore()
    ctx.strokeStyle = 'rgba(255,224,151,0.35)'
    ctx.lineWidth = 1.5
    ctx.beginPath(); ctx.arc(cx, cy, 152, 0, Math.PI * 2); ctx.stroke()
  }

  toast(text, icon = '✦', kind = '') {
    const stack = $('toast-stack')
    const el = document.createElement('div')
    el.className = `toast ${kind}`
    el.innerHTML = `<span class="t-icon">${icon}</span><span>${text}</span>`
    stack.appendChild(el)
    const timer = setTimeout(() => {
      el.classList.add('out')
      setTimeout(() => el.remove(), 420)
    }, 3200)
    this.toastTimers.push(timer)
  }

  showDialogue({ portrait, name, title, text, actions = [] }) {
    this.dialogueOpen = true
    $('dialogue').classList.remove('hidden')
    $('dialogue-portrait').textContent = portrait || name?.[0] || '?'
    $('dialogue-name').textContent = name
    $('dialogue-title').textContent = title
    $('dialogue-text').textContent = text
    const act = $('dialogue-actions')
    act.innerHTML = ''
    actions.forEach((a, i) => {
      const b = document.createElement('button')
      b.textContent = a.label
      b.onclick = () => {
        this.audio.click()
        this.closeDialogue()
        a.onClick?.()
      }
      act.appendChild(b)
    })
    this.audio.select()
  }

  closeDialogue() {
    this.dialogueOpen = false
    $('dialogue').classList.add('hidden')
  }

  openModal(html) {
    const layer = $('modal-layer')
    layer.innerHTML = html
    layer.classList.remove('hidden')
    this.modalOpen = true
    $('interact-prompt').classList.add('hidden')
    layer.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => this.closeModal()))
    this.audio.select()
  }

  closeModal() {
    this.modalOpen = false
    $('modal-layer').classList.add('hidden')
    $('modal-layer').innerHTML = ''
    $('interact-prompt').classList.add('hidden')
  }

  openAtlas() {
    if (this.mode !== 'world') return
    const p = this.state.player
    const cards = REGIONS.map(region => {
      const type = TYPES[region.type]
      const cleared = p.badges.includes(region.id)
      const current = p.regionId === region.id
      return `<button class="region-card ${current ? 'current' : ''} ${cleared ? 'cleared' : ''}" data-region="${region.id}" style="--rc:${type.color}">
        <div class="rc-top"><span class="rc-num">0${region.number}</span><span class="rc-type">${type.icon} ${type.name}</span></div>
        <h3>${region.name}</h3>
        <p>${region.subtitle}</p>
        <div class="rc-meta"><span>LV ${region.levelRange[0]}–${region.levelRange[1]}</span><span class="rc-badge ${cleared ? '' : 'locked'}">${region.gym.sigil} ${region.gym.badge}</span></div>
        <div class="rc-cta">${current ? 'You are here' : `Travel · ${region.gym.leader}`}</div>
      </button>`
    }).join('')
    const html = `<div class="modal-shell">
      <div class="modal-head">
        <div><div class="panel-eyebrow">WAYSTONE ATLAS</div><h2>The Eight Isles</h2><p>Danger rises with each isle. Your sigils open no doors — only your bond does.</p></div>
        <button class="modal-close" data-close>×</button>
      </div>
      <div class="modal-body">
        <div class="atlas-grid">${cards}</div>
        <div class="atlas-note">
          <span>${p.badges.length} / 8 sigils earned</span>
          <button class="text-btn" id="atlas-rest">✦ Rest & tend party</button>
        </div>
        <div style="display:flex;justify-content:flex-end;margin-top:14px"><button class="btn btn-primary" data-close><span>Close Atlas</span></button></div>
      </div>
    </div>`
    this.openModal(html)
    const layer = $('modal-layer')
    layer.querySelectorAll('[data-region]').forEach(b => {
      b.addEventListener('click', () => {
        const id = b.dataset.region
        if (id === this.state.player.regionId) { this.closeModal(); return }
        this.closeModal()
        $('flash').classList.add('on')
        setTimeout(() => $('flash').classList.remove('on'), 140)
        this.enterRegion(id)
      })
    })
    $('atlas-rest')?.addEventListener('click', () => {
      for (const c of p.party) {
        const st = statsFor(SPECIES[c.speciesId], c.level)
        c.hp = st.hp; c.maxHp = st.hp
      }
      this.audio.levelUp()
      this.toast('Party restored at the waystone.', '✦', 'good')
      this.save()
      this.openAtlas()
    })
  }

  openJournal(tab = 'craft') {
    if (this.mode !== 'world') return
    this.journalTab = tab
    const p = this.state.player
    const tabs = [['craft', 'Treat Crafting'], ['party', 'Party'], ['codex', 'Field Guide']]
    const inv = p.inventory || {}
    const treatTotal = Object.values(p.treats || {}).reduce((a, b) => a + b, 0)
    const ingTotal = Object.values(inv).reduce((a, b) => a + b, 0)
    let body = ''
    if (tab === 'craft') {
      const ingredients = Object.entries(INGREDIENTS).map(([id, ing]) => {
        const n = inv[id] || 0
        return `<div class="ing-chip"><span>${ing.icon}</span><span>${ing.name}</span><b>${n}</b></div>`
      }).join('')
      const recipes = Object.entries(TREATS).map(([type, treat]) => {
        const t = TYPES[type]
        const can = Object.entries(treat.recipe).every(([k, v]) => (inv[k] || 0) >= v)
        const req = Object.entries(treat.recipe).map(([k, v]) => `${INGREDIENTS[k].name} ${inv[k] || 0}/${v}`).join(' · ')
        return `<div class="craft-card" style="--tc:${t.color}">
          <div class="craft-icon">${treat.icon}</div>
          <h4>${treat.name}</h4>
          <div class="craft-type">${t.name} treat · ×${treat.yield}</div>
          <p>${treat.desc}</p>
          <div class="recipe-line"><span>${req}</span><b>×${p.treats?.[type] || 0}</b></div>
          <button class="craft-btn" data-craft="${type}" ${can ? '' : 'disabled'}>${can ? 'Craft Treat' : 'Need ingredients'}</button>
        </div>`
      }).join('')
      body = `<div class="bag-summary">
        <div class="bag-stat"><span>READY TREATS</span><b>${treatTotal}</b></div>
        <div class="bag-stat"><span>INGREDIENTS</span><b>${ingTotal}</b></div>
        <div class="bag-stat"><span>SIGILS</span><b>${p.badges.length} / 8</b></div>
      </div>
      <h3 class="journal-title">Field Ingredients</h3>
      <div class="inv-strip">${ingredients}</div>
      <h3 class="journal-title">Treat Recipes</h3>
      <div class="craft-grid">${recipes}</div>`
    } else if (tab === 'party') {
      body = `<div class="bag-summary">
        <div class="bag-stat"><span>PARTY</span><b>${p.party.length} / 6</b></div>
        <div class="bag-stat"><span>SANCTUARY</span><b>${p.reserve.length}</b></div>
        <div class="bag-stat"><span>KNOWN TITANS</span><b>${p.discovered.length} / ${Object.keys(SPECIES).length}</b></div>
      </div>
      <div class="party-grid">${p.party.map((c, i) => this.partyCard(c, i, true)).join('')}</div>
      ${p.reserve.length ? `<h3 class="journal-title" style="margin-top:22px">Sanctuary</h3><div class="reserve-list">${p.reserve.map((c, i) => {
        const sp = SPECIES[c.speciesId], t = TYPES[sp.type]
        return `<div class="reserve-card" style="--tc:${t.color}"><div><b>${sp.name}</b><span>Lv ${c.level} · ${t.name}</span></div><button class="mini-btn" data-reserve="${i}">Swap in</button></div>`
      }).join('')}</div>` : ''}`
    } else {
      const cards = Object.values(SPECIES).map(sp => {
        const known = p.discovered.includes(sp.speciesId || '')
        const seen = p.seen.includes(sp.id) || p.discovered.includes(sp.id)
        const t = TYPES[sp.type]
        return `<div class="codex-card ${seen ? 'seen' : 'empty-codex'}" style="--cc:${t.color}">
          <span>${known ? 'CAUGHT' : seen ? 'SEEN' : 'UNDISCOVERED'}</span>
          <h4>${seen ? sp.name : '???'}</h4>
          <p>${seen ? sp.epithet : 'The wilds keep this one hidden.'}</p>
        </div>`
      }).join('')
      body = `<div class="bag-summary">
        <div class="bag-stat"><span>REGISTERED</span><b>${p.discovered.length}</b></div>
        <div class="bag-stat"><span>SEEN IN THE WILD</span><b>${p.seen.length}</b></div>
        <div class="bag-stat"><span>REGIONS</span><b>${p.badges.length} / 8</b></div>
      </div><div class="codex-grid">${cards}</div>`
    }
    const html = `<div class="modal-shell">
      <div class="modal-head">
        <div><div class="panel-eyebrow">KEEPER'S JOURNAL</div><h2>${p.name}'s Field Notes</h2><p>Recipes, companions, and the titans you have met.</p></div>
        <button class="modal-close" data-close>×</button>
      </div>
      <div class="modal-body">
        <div class="journal-tabs">${tabs.map(([id, label]) => `<button class="tab-btn ${tab === id ? 'active' : ''}" data-tab="${id}">${label}</button>`).join('')}</div>
        ${body}
      </div>
    </div>`
    this.openModal(html)
    const layer = $('modal-layer')
    layer.querySelectorAll('[data-tab]').forEach(b => b.addEventListener('click', () => { this.audio.click(); this.openJournal(b.dataset.tab) }))
    layer.querySelectorAll('[data-craft]').forEach(b => b.addEventListener('click', () => this.craftTreat(b.dataset.craft)))
    layer.querySelectorAll('[data-lead]').forEach(b => b.addEventListener('click', () => {
      const i = Number(b.dataset.lead)
      if (p.party[i].hp <= 0) { this.audio.error(); this.toast('That titan needs rest first.', '◌', 'bad'); return }
      p.activeIndex = i
      this.refreshHUD(); this.save(); this.audio.select()
      this.openJournal('party')
    }))
    layer.querySelectorAll('[data-reserve]').forEach(b => b.addEventListener('click', () => {
      const idx = Number(b.dataset.reserve)
      const active = p.activeIndex || 0
      const reserveCreature = p.reserve[idx]
      const outgoing = p.party[active]
      p.party[active] = reserveCreature
      p.reserve[idx] = outgoing
      this.audio.select()
      this.toast(`${SPECIES[reserveCreature.speciesId].name} joins the party.`, '✦', 'good')
      this.save()
      this.openJournal('party')
    }))
  }

  partyCard(c, i, withActions) {
    const sp = SPECIES[c.speciesId]
    const t = TYPES[sp.type]
    const st = statsFor(sp, c.level)
    const moves = movesFor(sp, c.level).map(id => {
      const m = MOVES[id]
      return `<span class="pc-move" style="--mc:${TYPES[m.type].color}">${m.name}</span>`
    }).join('')
    return `<div class="party-card" style="--pc:${t.color}">
      <div class="party-orb">${t.icon}</div>
      <div><h4>${sp.name} ${i === this.state.player.activeIndex ? '<span style="color:#f2c96d;font-size:.55rem">LEAD</span>' : ''}</h4>
        <div class="pc-meta">${t.name} · Lv ${c.level} · ${c.nature || 'Curious'}</div>
        <div class="pc-hp"><i style="width:${clamp(c.hp / st.hp * 100, 0, 100)}%;background:${c.hp / st.hp < .3 ? '#ff766b' : '#78e4a2'}"></i></div>
        <div class="pc-info"><span>${c.hp} / ${st.hp} HP</span><span>XP ${c.xp} / ${xpToNext(c.level)}</span></div>
      </div>
      <div class="pc-moves">${moves}</div>
      ${withActions ? `<div class="pc-actions"><button class="mini-btn" data-lead="${i}" ${c.hp <= 0 ? 'disabled' : ''}>Set as lead</button></div>` : ''}
    </div>`
  }

  craftTreat(type) {
    const p = this.state.player
    const treat = TREATS[type]
    const inv = p.inventory
    for (const [k, v] of Object.entries(treat.recipe)) {
      if ((inv[k] || 0) < v) { this.audio.error(); this.toast('Not enough ingredients.', '◌', 'bad'); return }
    }
    for (const [k, v] of Object.entries(treat.recipe)) inv[k] -= v
    p.treats[type] = (p.treats[type] || 0) + treat.yield
    this.audio.select()
    this.toast(`Crafted ×${treat.yield} ${treat.name}`, treat.icon, 'good')
    this.save()
    this.openJournal('craft')
  }
}

