.starter-actions { position: absolute; right: 5vw; bottom: 2.2vh; display: flex; gap: 12px; pointer-events: auto; }
.starter-actions .btn { min-height: 46px; }
.starter-actions .btn-ghost { font-size: 0.63rem; }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 12; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button, #hud .party-dock, #hud .badge-rack, #hud .minimap-wrap { pointer-events: auto; }
.hud-top { position: absolute; top: 0; left: 0; right: 0; padding: 22px 28px; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
.hud-left { display: flex; flex-direction: column; gap: 10px; }
.region-badge { display: flex; align-items: center; gap: 13px; padding: 11px 15px 11px 12px; background: linear-gradient(100deg, rgba(10,15,27,0.82), rgba(10,15,27,0.3)); border-left: 2px solid var(--gold); backdrop-filter: blur(14px); min-width: 288px; }
.region-index { font-family: var(--serif); font-size: 1.55rem; color: var(--gold); opacity: 0.8; }
.region-badge strong { display: block; font-family: var(--serif); font-size: 1.02rem; letter-spacing: 0.05em; font-weight: 500; }
.region-badge div span { display: block; margin-top: 2px; font-size: 0.56rem; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(255,248,231,0.48); }
.region-type { margin-left: auto; font-size: 0.49rem; letter-spacing: 0.17em; text-transform: uppercase; color: var(--type, var(--teal)); border: 1px solid color-mix(in srgb, var(--type, var(--teal)) 40%, transparent); padding: 4px 7px; background: color-mix(in srgb, var(--type, var(--teal)) 9%, transparent); }
.objective { display: flex; align-items: center; gap: 11px; padding: 9px 14px; min-width: 268px; }
.obj-mark { color: var(--gold); font-size: 1rem; }
.objective b { display: block; font-size: 0.48rem; letter-spacing: 0.22em; color: var(--gold); font-weight: 600; }
.objective span:last-child { display: block; margin-top: 3px; font-size: 0.7rem; color: rgba(255,248,231,0.72); }
.hud-center { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.badge-rack { display: flex; gap: 7px; padding: 8px 11px; border-radius: 2px; }
.badge-slot { width: 28px; height: 34px; display: grid; place-items: center; clip-path: polygon(50% 0, 93% 24%, 85% 82%, 50% 100%, 15% 82%, 7% 24%); background: rgba(255,255,255,0.055); border: 1px solid rgba(255,255,255,0.12); font-size: 0.75rem; color: rgba(255,255,255,0.19); position: relative; }
.badge-slot.earned { background: linear-gradient(160deg, color-mix(in srgb, var(--bc) 45%, #111), color-mix(in srgb, var(--bc) 15%, #0a0f1b)); color: var(--bc); text-shadow: 0 0 12px var(--bc); box-shadow: 0 0 16px color-mix(in srgb, var(--bc) 25%, transparent); }
.badge-slot.earned::after { content: ''; position: absolute; inset: 4px; border: 1px solid color-mix(in srgb, var(--bc) 40%, transparent); clip-path: inherit; }
.keeper-chip { display: flex; align-items: center; gap: 9px; padding: 7px 13px 7px 7px; background: rgba(10,15,27,0.6); border: 1px solid var(--line); backdrop-filter: blur(12px); }
.keeper-chip > span { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(145deg, #f4d889, #b7882e); color: #19130a; font-family: var(--serif); font-size: 0.95rem; font-weight: 700; }
.keeper-chip b { display: block; font-size: 0.68rem; letter-spacing: 0.08em; }
.keeper-chip i { display: block; margin-top: 2px; font-size: 0.48rem; color: var(--gold); letter-spacing: 0.13em; text-transform: uppercase; font-style: normal; }
.hud-right { display: flex; align-items: flex-start; gap: 13px; }
.minimap-wrap { position: relative; width: 150px; height: 150px; border-radius: 50%; overflow: hidden; border: 1px solid rgba(255,224,151,0.24); background: radial-gradient(circle at 50% 50%, rgba(20,30,41,0.85), rgba(7,11,19,0.95)); }
#minimap { width: 100%; height: 100%; display: block; }
.map-n { position: absolute; top: 7px; left: 50%; transform: translateX(-50%); font-size: 0.47rem; letter-spacing: 0.15em; color: var(--gold); }
.map-caption { position: absolute; bottom: 11px; left: 50%; transform: translateX(-50%); font-size: 0.4rem; letter-spacing: 0.12em; white-space: nowrap; color: rgba(255,248,231,0.55); }
.hud-buttons { display: flex; flex-direction: column; gap: 7px; }
.hud-btn { width: 61px; height: 43px; border: 1px solid var(--line); background: rgba(9,14,25,0.64); backdrop-filter: blur(12px); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; border-radius: 2px; transition: 0.18s; }
.hud-btn span { color: var(--gold); font-size: 0.84rem; line-height: 1; }
.hud-btn b { font-size: 0.38rem; letter-spacing: 0.14em; font-weight: 500; color: rgba(255,248,231,0.55); }
.hud-btn:hover { border-color: var(--line-strong); background: rgba(22,32,50,0.8); }
.hud-bottom { position: absolute; bottom: 0; left: 0; right: 0; padding: 0 28px 20px; display: flex; justify-content: space-between; align-items: flex-end; gap: 20px; }
.party-dock { display: flex; gap: 7px; align-items: flex-end; }
.party-pill { width: 96px; height: 52px; display: flex; align-items: center; gap: 8px; padding: 6px 8px; background: linear-gradient(120deg, rgba(13,20,34,0.85), rgba(9,13,22,0.7)); border: 1px solid var(--line); position: relative; overflow: hidden; border-radius: 2px; transition: 0.2s; }
.party-pill.active { border-color: var(--bc, var(--gold)); }
.party-pill .orb { flex: 0 0 30px; width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font-size: 0.8rem; color: var(--bc); background: radial-gradient(circle at 36% 32%, color-mix(in srgb, var(--bc) 50%, #fff), color-mix(in srgb, var(--bc) 25%, #10182a) 64%, #070b14); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bc) 30%, transparent); }
.party-pill b { display: block; font-size: 0.52rem; font-weight: 600; letter-spacing: 0.04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 50px; }
.party-pill span { display: block; font-size: 0.4rem; color: rgba(255,248,231,0.48); margin-top: 2px; }
.party-pill .mini-hp { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: rgba(255,255,255,0.1); }
.party-pill .mini-hp i { display: block; height: 100%; background: var(--ok); transition: width 0.3s; }
.party-pill.fainted { opacity: 0.42; filter: grayscale(0.8); }
.control-hints { display: flex; gap: 14px; font-size: 0.48rem; letter-spacing: 0.1em; color: rgba(255,248,231,0.37); text-transform: uppercase; padding-bottom: 4px; }
