.modal-body { padding: 0 30px 30px; }

/* atlas */
.atlas-tabs, .journal-tabs { display: flex; gap: 5px; border-bottom: 1px solid var(--line); margin-bottom: 20px; }
.tab-btn { border: 0; border-bottom: 2px solid transparent; background: transparent; padding: 9px 14px; font-size: 0.6rem; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(255,248,231,0.46); }
.tab-btn.active { color: var(--gold-2); border-bottom-color: var(--gold); }
.atlas-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
#battle-tooltip { position: absolute; left: 50%; bottom: 215px; transform: translateX(-50%); max-width: 440px; padding: 11px 16px; font-size: 0.62rem; line-height: 1.55; background: rgba(8,13,23,0.96); border: 1px solid var(--line); }
.dmg-float { position: absolute; z-index: 35; font-family: var(--serif); font-weight: 700; font-size: 2.1rem; color: #fff1c4; text-shadow: 0 2px 15px rgba(0,0,0,0.75), 0 0 18px rgba(255,209,112,0.45); pointer-events: none; animation: dmgFloat 1.15s ease-out both; }
.dmg-float.crit { color: #ffd05e; font-size: 2.8rem; }
.dmg-float.heal { color: #8bf3ae; }
@keyframes dmgFloat { 0% { opacity: 0; transform: translate(-50%, 8px) scale(0.75); } 18% { opacity: 1; transform: translate(-50%, 0) scale(1.1); } 100% { opacity: 0; transform: translate(-50%, -55px) scale(0.92); } }
.shake { animation: shakeIt 0.42s ease; }
@keyframes shakeIt { 0%,100%{ transform: translate(0,0); } 20%{ transform: translate(-7px,4px); } 40%{ transform: translate(6px,-5px); } 60%{ transform: translate(-4px,-2px); } 80%{ transform: translate(3px,3px); } }

