.btn { border: 0; position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 26px; min-height: 54px; padding: 0 28px; border-radius: 3px; font-weight: 600; letter-spacing: 0.09em; font-size: 0.78rem; text-transform: uppercase; transition: transform 0.18s ease, background 0.18s, box-shadow 0.18s; }
.btn:hover { transform: translateY(-2px); }
.btn-primary { color: #17130b; background: linear-gradient(110deg, #ffe6a3, #d4a845 72%, #a87b28); box-shadow: 0 12px 34px rgba(212, 168, 69, 0.27), inset 0 1px rgba(255,255,255,0.5); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%); }
.btn-primary:hover { box-shadow: 0 18px 42px rgba(212, 168, 69, 0.38), inset 0 1px rgba(255,255,255,0.6); }
.btn-primary i { font-style: normal; font-size: 1.1rem; }
.btn-ghost { background: rgba(14, 21, 37, 0.55); border: 1px solid var(--line); color: var(--cream); }
.btn-ghost:hover { border-color: var(--line-strong); background: rgba(22, 32, 52, 0.7); }
.btn-ghost i { color: var(--gold); font-style: normal; }
