}

function addBroadleaf(group, rng, mats, scale = 1, color) {
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.035 * scale, 0.075 * scale, 1.2 * scale, 5), mats.wood)
  stem.position.y = 0.6 * scale
