    const centre = new THREE.Mesh(new THREE.SphereGeometry(0.07 * scale, 6, 5), material('#f6d36d', { emissive: '#ffd264', emissiveIntensity: 0.18, roughness: 0.5 }))
    centre.position.y = 1.24 * scale
    group.add(centre)
  }
